INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('davidkelley/searchlite/bug-hunting', 'bug-hunting', 'davidkelley', 'searchlite', 'community', 'bug-hunting davidkelley searchlite community Searchlite 是一个小型的嵌入式搜索引擎，提供 Rust API、CLI 和可选的 C/WASM 绑定，适合开发人员使用 Searchlite は、小型の埋め込み可能な検索エンジンであり、Rust API、CLI、およびオプションの C/WASM バインディングを提供します Searchlite는 작은 임베디드 검색 엔진으로, Rust API, CLI 및 선택적 C/WASM 바인딩을 제공합니다 Searchlite es un motor de búsqueda integrado que ofrece una API de Rust y CLI para búsqueda de texto completo Searchlite est un moteur de recherche intégré qui offre une API Rust et CLI pour la recherche de texte complet Searchlite ist eine eingebettete Suchmaschine, die eine Rust-API und CLI für die Volltextsuche bietet Searchlite é um mecanismo de busca incorporado que oferece uma API em Rust, CLI e recursos de busca em texto completo para desenvolvedores Searchlite - это встроенный поисковый движок, который предоставляет API на Rust, CLI и функции полнотекстового поиска для разработчиков Searchlite هو محرك بحث مدمج يقدم واجهة برمجة تطبيقات Rust وواجهة سطر أوامر وخصائص البحث النصي الكامل للمطورين 🔍 Searchlite is an embedded search engine that keeps a single on‑disk index and exposes a clean Rust API, CLI, and optional C/WASM bindings. It offers BM25 with phrase matching, filters/aggregations, stored fields, highlighting, and optional vectors/GPU stubs for fast, schema-driven full‑text se... 如何使用 Searchlite Searchlite 教程 全文搜索工具 Searchlite 安装 Searchlite 设置指南 Searchlite 与 Elasticsearch 比较 🔍 Searchlite is an embedded search engine that keeps a single on‑disk index and exposes a clean Rust API, CLI, and optional C/WASM bindings. It offers BM25 with phrase matching, filters/aggregations, stored fields, highlighting, and optional vectors/GPU stubs for fast, schema-driven full‑text search in a small footprint.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jtordoya-dev/Antigravity_setup/popup-cro', 'community', 'jtordoya-dev', 'Antigravity_setup', 'jtordoya-dev/Antigravity_setup', 'popup-cro', 0, 0, 50, '2026-03-04T13:07:01.760Z', '2026-03-04T14:15:23.740Z', '0d37211c60d0ef1a67deef75f2f31feb79788cf33a0a7ed573a6c119c83219ae', '{"id":"jtordoya-dev/Antigravity_setup/popup-cro","name":"popup-cro","description":{"zh":"popup-cro入门套件是开发者提升工作效率的必备工具，提供简洁的开发环境","ja":"popup-croスターター キットは開発者の生産性を向上させるための必須ツールです","ko":"popup-cro 시작 키트는 개발자의 생산성을 높이는 데 필요한 기본 도구입니다","es":"El kit de inicio para popup-cro es una herramienta de AI que ayuda a los desarrolladores a crear soluciones personalizadas","fr":"Le kit de démarrage pour popup-cro est un outil d''IA qui aide les développeurs à créer des solutions sur mesure","de":"Das Starter-Kit für popup-cro ist ein KI-Tool, das Entwicklern hilft, maßgeschneiderte Lösungen zu erstellen","pt":"O popup-cro é um kit de início para desenvolvedores que buscam criar soluções de AI inovadoras com React, Python e Node.js","ru":"ИИ Агенты: popup-cro - набор для начала работы с ИИ для разработчиков, ищущих создать инновационные решения с помощью React, Python и Node.js","ar":"أدوات الذكاء الاصطناعي: popup-cro حزمة بدء للمانحين الذين يبحثون عن إنشاء حلول ذكاء اصطناعي مبتكرة باستخدام React، Python و Node.js","en":"Kit de Inicio"},"seo":{"title":{"zh":"AI智能工具popup-cro入门套件","ja":"AIエージェントpopup-croスターター キット","ko":"AI 에이전트 popup-cro 시작 키트","es":"Herramientas de AI: Kit de Inicio para popup-cro","fr":"Outils d''IA: Kit de démarrage pour popup-cro","de":"KI-Tools: Starter-Kit für popup-cro","pt":"Ferramentas de AI: popup-cro Kit de Inicio","ru":"ИИ Агенты: popup-cro Набор для начала","ar":"أدوات الذكاء الاصطناعي: popup-cro حزمة البدء","en":"popup-cro"},"description":{"zh":"popup-cro入门套件是开发者提升工作效率的必备工具，提供简洁的开发环境","ja":"popup-croスターター キットは開発者の生産性を向上させる