INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pwittchen/varun.surf/profile-blocking', 'profile-blocking', 'pwittchen', 'varun.surf', 'community', 'profile-blocking pwittchen varun.surf community profile-blocking 是一个为风筝运动爱好者提供的 AI 智能工具，包含风筝运动爱好者数据库和天气预报 profile-blocking は、カイトスポットデータベースと天気予報を提供する AI エージェントです profile-blocking은 카이트서핑 데이터베이스 및 날씨 예보를 제공하는 AI 에이전트입니다 La herramienta de perfil de bloqueo ofrece una base de datos de spots de kite y pronóstico del tiempo para kitesurfers en la web L''outil de blocage de profil propose une base de données de spots de kite et une prévision météo pour kitesurfers sur le web Das Kitesurf-Profil-Blockierungstool bietet eine Kite-Spot-Datenbank und Wettervorhersage für Kitesurfer im Internet O profile-blocking é uma ferramenta de IA que fornece um banco de dados de spots de kitesurf e previsão do tempo para ajudar os kitesurfistas a planejar suas sessões Profile-blocking - это инструмент ИИ, который предоставляет базу данных спотов для кайтсёрфинга и прогноз погоды, чтобы помочь кайтсёрферам планировать свои сессии أداة profile-blocking هي أداة ذكاء اصطناعي توفر قاعدة بيانات للمواقع الرائدة وتنبؤات الطقس لمساعدة الرائدين في تخطيط جلساتهم 🏄 kite spots database and weather forecast for kitesurfers on the web 如何使用 profile-blocking 什么是 profile-blocking profile-blocking 替代品 profile-blocking 安装 profile-blocking 教程 AI 智能工具 风筝运动爱好者数据库 天气预报 🏄 kite spots database and weather forecast for kitesurfers on the web');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kettleofketchup/DraftForge/frontend-dev-guidelines', 'community', 'kettleofketchup', 'DraftForge', 'kettleofketchup/DraftForge', 'frontend-dev-guidelines', 0, 0, 49, '2026-03-04T13:07:01.695Z', '2026-03-04T13:36:13.028Z', 'e8187169648aa60b3828fde643b0046a343cff7984887e40c3966c791efcc7c8', '{"id":"kettleofketchup/DraftForge/frontend-dev-guidelines","name":"frontend-dev-guidelines","description":{"zh":"AI智能代理提供了前端开发的最佳实践和指南，帮助开发者提高代码质量和开发效率，特别是对于Dota 2 Event Coordinator的开发","ja":"AIエージェントはフロントエンド開発のベストプラクティスとガイドラインを提供し、開発者のコード品質と開発効率を向上させる、特にDota 2 Event Coordinatorの開発において","ko":"AI 에이전트는 프론트엔드 개발의 베스트 프랙티스와 가이드라인을 제공하여 개발자의 코드 품질과 개발 효율을 향상시키며, 특히 Dota 2 Event Coordinator의 개발에 중점을 둡니다","es":"Guías de desarrollo frontend para Dota 2, incluyendo mejores prácticas y herramientas para desarrolladores","fr":"Guides de développement frontend pour Dota 2, incluant les meilleures pratiques et outils pour les développeurs","de":"Frontend-Entwicklungsguides für Dota 2, einschließlich Best Practices und Tools für Entwickler","pt":"A ferramenta de AI para desenvolvimento frontend fornece diretrizes para melhorar a qualidade do código e a experiência do usuário.","ru":"ИИ Агент для frontend-разработки предоставляет руководство по улучшению качества кода и пользовательского опыта.","ar":"أداة الذكاء الاصطناعي لتطوير الواجهة الأمامية توفر إرشادات لتحسين جودة الكود وتجربة المستخدم.","en":"Dota 2 Event Coordinator"},"seo":{"title":{"zh":"AI智能代理-前端开发指南","ja":"AIエージェント-フロントエンド開発ガイドライン","ko":"AI 에이전트-프론트엔드 개발 가이드라인","es":"Herramientas de desarrollo frontend para Dota 2","fr":"Outils de développement frontend pour Dota 2","de":"Frontend-Entwicklungstools für Dota 2","pt":"Ferramentas de Desenvolvimento Frontend: Diretrizes para ...","ru":"ИИ Агенты для Frontend-разработки: Руководство","ar":"أدوات تطوير الواجهة الأمامية: إرشادات للمطورين","en":"frontend-dev-guidelines"},"description":{"zh":"AI智能代理提供了前端开发的最佳实践和指南，帮助开发者提高代码质量和开发效率，特别是对于Dota 2 Event Coordinator的开发","ja":"AIエージェントはフロントエンド開発のベストプラクティスとガイドラインを提供し、開発者のコード品質と開発効率を向上させる、特にDota 2 Event Coordinatorの開発において","ko":"AI 에이전트는 프론트엔드 개발의 베스트 프랙티스와 가이드라인을 제공하여 개발자의 코드 품질과 개발 효율을 향상시키며, 특히 Dota 2 Event Coordinator의 개발에 중점을 둡니다","es":"Guías de desarrollo frontend para Dota 2, incluyendo mejores prácticas y herramientas para desarrolladores","fr":"Guides de développement frontend pour Dota 2, incluant les meilleures pratiques et outils pour les développeurs","de":"Frontend-Entwicklungsguides für Dota 2, einschließlich Best Practices und Tools für Entwickler","pt":"A ferramenta de AI para desenvolvimento frontend fornece diretrizes para melhorar a qualidade do código e a experiência do usuário.","ru":"ИИ Агент для frontend-разработки предоставляет руководство по улучшению качества кода и пользовательского опыта.","ar":"أداة الذكاء الاصطناعي لتطوير الواجهة الأمامية توفر إرشادات لتحسين جودة الكود وتجربة المستخدم.","en":"Dota 2 Event Coordinator"},"definition":{"en":"Dota 2 Event Coordinator"},"features":{"zh":["提供前端开发的最佳实践和指南","支持Dota 2 Event Coordinator的开发","使用AI技术来优化代码质量和开发效率","集成React、Python、Node.js等流行的前端开发技术","提供CLI工具来简化开发流程"],"ja":["フロントエンド開発のベストプラクティスとガイドラインを提供","Dota 2 Event Coordinatorの開発をサポート","AI技術を使用してコード品質と開発効率を最適化","React、Python、Node.jsなどの人気のあるフロントエンド開発技術をサポート","CLIツールを提供して開発プロセスを簡素化"],"ko":["프론트엔드 개발의 베스트 프랙티스와 가이드라인을 제공","Dota 2 Event Coordinator의 개발을 지원","AI 기술을 사용하여 코드 품질과 개발 효율을 최적화","React, Python, Node.js 등의 인기 있는 프론트엔드 개발 기술을 지원","CLI 도구를 제공하여 개발 프로세스를 간소화"],"es":["Guías de desarrollo frontend para Dota 2","Herramientas de desarrollo de interfaz de usuario","Mejores prácticas para desarrolladores frontend","Integración con la API de Dota 2","Soporte para desarrollo de aplicaciones web"],"fr":["Guides de développement frontend pour Dota 2","Outils de développement d''interface utilisateur","Meilleures pratiques pour les développeurs frontend","Intégration avec l''API de Dota 2","Prise en charge du développement d''applications web"],"de":["Frontend-Entwicklungsguides für Dota 2","Tools für die Entwicklung von Benutzeroberflächen","Best Practices für Frontend-Entwickler","Integration mit der Dota-2-API","Unterstützung für die Entwicklung von Webanwendungen"],"pt":["Otimização de código","Melhoria da experiência do usuário","Diretrizes para desenvolvimento frontend","Integração com React e Node.js","Suporte a CLI"],"ru":["Оптимизация кода","Улучшение пользовательского опыта","Руководство по frontend-разработке","Интеграция с React и Node.js","Поддержка CLI"],"ar":["تحسين الكود","تحسين تجربة المستخدم","إرشادات لتطوير الواجهة الأمامية","التكامل مع React و Node.js","دعم CLI"]},"keywords":{"zh":["AI智能代理","前端开发指南","Dota 2 Event Coordinator","如何使用AI智能代理","AI智能代理的优点","前端开发最佳实践","React开发指南","Python开发指南","Node.js开发指南"],"ja":["AIエージェント","フロントエンド開発ガイドライン","Dota 2 Event Coordinator","AIエージェントの使用方法","AIエージェントの利点","フロントエンド開発ベストプラクティス","React開発ガイド","Python開発ガイド","Node.js開発ガイド"],"ko":["AI 에이전트","프론트엔드 개발 가이드라인","Dota 2 Event Coordinator","AI 에이전트 사용 방법","AI 에이전트의 장점","프론트엔드 개발 베스트 프랙티스","React 개발 가이드","Python 개발 가이드","Node.js 개발 가이드"],"es":["desarrollo frontend","herramientas de desarrollo","Dota 2","guías de desarrollo","mejores prácticas","desarrollo de aplicaciones web","API de Dota 2","alternativas a React","Node.js para Dota 2"],"fr":["développement frontend","outils de développement","Dota 2","guides de développement","meilleures pratiques","développement d''applications web","API de Dota 2","alternatives à React","Node.js pour Dota 2"],"de":["Frontend-Entwicklung","Entwicklungstools","Dota 2","Entwicklungsguides","Best Practices","Entwicklung von Webanwendungen","Dota-2-API","Alternativen zu React","Node.js für Dota 2"],"pt":["ferramentas de desenvolvimento frontend","como usar AI para desenvolvimento","otimização de código","melhoria da experiência do usuário","React vs Angular","Node.js install"],"ru":["ИИ Агенты для frontend-разработки","как использовать ИИ для разработки","оптимизация кода","улучшение пользовательского опыта","React vs Angular","установка Node.js"],"ar":["أدوات تطوير الواجهة الأمامية","كيفية استخدام الذكاء الاصطناعي لتطوير","تحسين الكود","تحسين تجربة المستخدم","React vs Angular","تثبيت Node.js"]}},"owner":"kettleofketchup","repo":"DraftForge","repoPath":"kettleofketchup/DraftForge","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.695Z","topics":[],"category":"community","skillMd":{"name":"frontend-dev-guidelines","description":"Frontend development guidelines for React/TypeScript applications. Modern patterns including Suspense, lazy loading, useSuspenseQuery, file organization with features directory, MUI v7 styling, TanStack Router, performance optimization, and TypeScript best practices. Use when creating components, pages, features, fetching data, styling, routing, or working with frontend code.","bodyPreview":"# Frontend Development Guidelines\n\n## Purpose\n\nComprehensive guide for modern React development, emphasizing Suspense-based data fetching, lazy loading, proper file organization, and performance optimization.\n\n## When to Use This Skill\n\n- Creating new components or pages\n- Building new features\n- Fetching data with TanStack Query\n- Setting up routing with TanStack Router\n- Styling components with MUI v7\n- Performance optimization\n- Organizing frontend code\n- TypeScript best practices\n\n---\n\n## Qu","body":"# Frontend Development Guidelines\n\n## Purpose\n\nComprehensive guide for modern React development, emphasizing Suspense-based data fetching, lazy loading, proper file organization, and performance optimization.\n\n## When to Use This Skill\n\n- Creating new components or pages\n- Building new features\n- Fetching data with TanStack Query\n- Setting up routing with TanStack Router\n- Styling components with MUI v7\n- Performance optimization\n- Organizing frontend code\n- TypeScript best practices\n\n---\n\n## Quick Start\n\n### New Component Checklist\n\nCreating a component? Follow this checklist:\n\n- [ ] Use `React.FC<Props>` pattern with TypeScript\n- [ ] Lazy load if heavy component: `React.lazy(() => import())`\n- [ ] Wrap in `<SuspenseLoader>` for loading states\n- [ ] Use `useSuspenseQuery` for data fetching\n- [ ] Import aliases: `@/`, `~types`, `~components`, `~features`\n- [ ] Styles: Inline if <100 lines, separate file if >100 lines\n- [ ] Use `useCallback` for event handlers passed to children\n- [ ] Default export at bottom\n- [ ] No early returns with loading spinners\n- [ ] Use `useMuiSnackbar` for user notifications\n\n### New Feature Checklist\n\nCreating a feature? Set up this structure:\n\n- [ ] Create `features/{feature-name}/` directory\n- [ ] Create subdirectories: `api/`, `components/`, `hooks/`, `helpers/`, `types/`\n- [ ] Create API service file: `api/{feature}Api.ts`\n- [ ] Set up TypeScript types in `types/`\n- [ ] Create route in `routes/{feature-name}/index.tsx`\n- [ ] Lazy load feature components\n- [ ] Use Suspense boundaries\n- [ ] Export public API from feature `index.ts`\n\n---\n\n## Import Aliases Quick Reference\n\n| Alias | Resolves To | Example |\n|-------|-------------|---------|\n| `@/` | `src/` | `import { apiClient } from ''@/lib/apiClient''` |\n| `~types` | `src/types` | `import type { User } from ''~types/user''` |\n| `~components` | `src/components` | `import { SuspenseLoader } from ''~components/SuspenseLoader''` |\n| `~features` | `src/features` | `import { authApi } from ''~features/auth''` |\n\nDefined in: [vite.config.ts](../../vite.config.ts) lines 180-185\n\n---\n\n## Common Imports Cheatsheet\n\n```typescript\n// React & Lazy Loading\nimport React, { useState, useCallback, useMemo } from ''react'';\nconst Heavy = React.lazy(() => import(''./Heavy''));\n\n// MUI Components\nimport { Box, Paper, Typography, Button, Grid } from ''@mui/material'';\nimport type { SxProps, Theme } from ''@mui/material'';\n\n// TanStack Query (Suspense)\nimport { useSuspenseQuery, useQueryClient } from ''@tanstack/react-query'';\n\n// TanStack Router\nimport { createFileRoute } from ''@tanstack/react-router'';\n\n// Project Components\nimport { SuspenseLoader } from ''~components/SuspenseLoader'';\n\n// Hooks\nimport { useAuth } from ''@/hooks/useAuth'';\nimport { useMuiSnackbar } from ''@/hooks/useMuiSnackbar'';\n\n// Types\nimport type { Post } from ''~types/post'';\n```\n\n---\n\n## Topic Guides\n\n### 🎨 Component Patterns\n\n**Modern React components use:**\n- `React.FC<Props>` for type safety\n- `React.lazy()` for code splitting\n- `SuspenseLoader` for loading states\n- Named const + default export pattern\n\n**Key Concepts:**\n- Lazy load heavy components (DataGrid, charts, editors)\n- Always wrap lazy components in Suspense\n- Use SuspenseLoader component (with fade animation)\n- Component structure: Props → Hooks → Handlers → Render → Export\n\n**[📖 Complete Guide: resources/component-patterns.md](resources/component-patterns.md)**\n\n---\n\n### 📊 Data Fetching\n\n**PRIMARY PATTERN: useSuspenseQuery**\n- Use with Suspense boundaries\n- Cache-first strategy (check grid cache before API)\n- Replaces `isLoading` checks\n- Type-safe with generics\n\n**API Service Layer:**\n- Create `features/{feature}/api/{feature}Api.ts`\n- Use `apiClient` axios instance\n- Centralized methods per feature\n- Route format: `/form/route` (NOT `/api/form/route`)\n\n**[📖 Complete Guide: resources/data-fetching.md](resources/data-fetching.md)**\n\n---\n\n### 📁 File Organization\n\n**features/ vs components/:**\n- `features/`: Domain-specific (posts, comments, auth)\n- `components/`: Truly reusable (SuspenseLoader, CustomAppBar)\n\n**Feature Subdirectories:**\n```\nfeatures/\n  my-feature/\n    api/          # API service layer\n    components/   # Feature components\n    hooks/        # Custom hooks\n    helpers/      # Utility functions\n    types/        # TypeScript types\n```\n\n**[📖 Complete Guide: resources/file-organization.md](resources/file-organization.md)**\n\n---\n\n### 🎨 Styling\n\n**Inline vs Separate:**\n- <100 lines: Inline `const styles: Record<string, SxProps<Theme>>`\n- >100 lines: Separate `.styles.ts` file\n\n**Primary Method:**\n- Use `sx` prop for MUI components\n- Type-safe with `SxProps<Theme>`\n- Theme access: `(theme) => theme.palette.primary.main`\n\n**MUI v7 Grid:**\n```typescript\n<Grid size={{ xs: 12, md: 6 }}>  // ✅ v7 syntax\n<Grid xs={12} md={6}>             // ❌ Old syntax\n```\n\n**[📖 Complete Guide: resources/styling-guide.md](resources/styling-guide.md)**\n\n---\n\n### 🛣️ Routing\n\n**TanStack Router - Folder-Based:**\n- Directory: `routes/my-route/index.tsx`\n- Lazy load components\n- Use `createFileRoute`\n- Breadcrumb data in loader\n\n**Example:**\n```typescript\nimport { createFileRoute } from ''@tanstack/react-router'';\nimport { lazy } from ''react'';\n\nconst MyPage = lazy(() => import(''@/features/my-feature/components/MyPage''));\n\nexport const Route = createFileRoute(''/my-route/'')({\n    component: MyPage,\n    loader: () => ({ crumb: ''My Route'' }),\n});\n```\n\n**[📖 Complete Guide: resources/routing-guide.md](resources/routing-guide.md)**\n\n---\n\n### ⏳ Loading & Error States\n\n**CRITICAL RULE: No Early Returns**\n\n```typescript\n// ❌ NEVER - Causes layout shift\nif (isLoading) {\n    return <LoadingSpinner />;\n}\n\n// ✅ ALWAYS - Consistent layout\n<SuspenseLoader>\n    <Content />\n</SuspenseLoader>\n```\n\n**Why:** Prevents Cumulative Layout Shift (CLS), better UX\n\n**Error Handling:**\n- Use `useMuiSnackbar` for user feedback\n- NEVER `react-toastify`\n- TanStack Query `onError` callbacks\n\n**[📖 Complete Guide: resources/loading-and-error-states.md](resources/loading-and-error-states.md)**\n\n---\n\n### ⚡ Performance\n\n**Optimization Patterns:**\n- `useMemo`: Expensive computations (filter, sort, map)\n- `useCallback`: Event handlers passed to children\n- `React.memo`: Expensive components\n- Debounced search (300-500ms)\n- Memory leak prevention (cleanup in useEffect)\n\n**[📖 Complete Guide: resources/performance.md](resources/performance.md)**\n\n---\n\n### 📘 TypeScript\n\n**Standards:**\n- Strict mode, no `any` type\n- Explicit return types on functions\n- Type imports: `import type { User } from ''~types/user''`\n- Component prop interfaces with JSDoc\n\n**[📖 Complete Guide: resources/typescript-standards.md](resources/typescript-standards.md)**\n\n---\n\n### 🔧 Common Patterns\n\n**Covered Topics:**\n- React Hook Form with Zod validation\n- DataGrid wrapper contracts\n- Dialog component standards\n- `useAuth` hook for current user\n- Mutation patterns with cache invalidation\n\n**[📖 Complete Guide: resources/common-patterns.md](resources/common-patterns.md)**\n\n---\n\n### 👤 User Avatars\n\n**ALWAYS use `AvatarUrl` helper** for user avatars - handles empty strings, Discord IDs, and fallback generation.\n\n```typescript\nimport { AvatarUrl } from \"~/components/user/avatar\";\n<img src={AvatarUrl(user)} />\n```\n\n**[📖 Complete Guide: resources/user-avatar.md](resources/user-avatar.md)**\n\n---\n\n### 📚 Complete Examples\n\n**Full working examples:**\n- Modern component with all patterns\n- Complete feature structure\n- API service layer\n- Route with lazy loading\n- Suspense + useSuspenseQuery\n- Form with validation\n\n**[📖 Complete Guide: resources/complete-examples.md](resources/complete-examples.md)**\n\n---\n\n## Navigation Guide\n\n| Need to... | Read this resource |\n|------------|-------------------|\n| Create a component | [component-patterns.md](resources/component-patterns.md) |\n| Fetch data | [data-fetching.md](resources/data-fetching.md) |\n| Organize files/folders | [file-organization.md](resources/file-organization.md) |\n| Style components | [styling-guide.md](resources/styling-guide.md) |\n| Set up routing | [routing-guide.md](resources/routing-guide.md) |\n| Handle loading/errors | [loading-and-error-states.md](resources/loading-and-error-states.md) |\n| Optimize performance | [performance.md](resources/performance.md) |\n| TypeScript types | [typescript-standards.md](resources/typescript-standards.md) |\n| Forms/Auth/DataGrid | [common-patterns.md](resources/common-patterns.md) |\n| Display user avatars | [user-avatar.md](resources/user-avatar.md) |\n| See full examples | [complete-examples.md](resources/complete-examples.md) |\n\n---\n\n## Core Principles\n\n1. **Lazy Load Everything Heavy**: Routes, DataGrid, charts, editors\n2. **Suspense for Loading**: Use SuspenseLoader, not early returns\n3. **useSuspenseQuery**: Primary data fetching pattern for new code\n4. **Features are Organized**: api/, components/, hooks/, helpers/ subdirs\n5. **Styles Based on Size**: <100 inline, >100 separate\n6. **Import Aliases**: Use @/, ~types, ~components, ~features\n7. **No Early Returns**: Prevents layout shift\n8. **useMuiSnackbar**: For all user notifications\n\n---\n\n## Quick Reference: File Structure\n\n```\nsrc/\n  features/\n    my-feature/\n      api/\n        myFeatureApi.ts       # API service\n      components/\n        MyFeature.tsx         # Main component\n        SubComponent.tsx      # Related components\n      hooks/\n        useMyFeature.ts       # Custom hooks\n        useSuspenseMyFeature.ts  # Suspense hooks\n      helpers/\n        myFeatureHelpers.ts   # Utilities\n      types/\n        index.ts              # TypeScript types\n      index.ts                # Public exports\n\n  components/\n    SuspenseLoader/\n      SuspenseLoader.tsx      # Reusable loader\n    CustomAppBar/\n      CustomAppBar.tsx        # Reusable app bar\n\n  routes/\n    my-route/\n      index.tsx               # Route component\n      create/\n        index.tsx             # Nested route\n```\n\n---\n\n## Modern Component Template (Quick Copy)\n\n```typescript\nimport React, { useState, useCallback } from ''react'';\nimport { Box, Paper } from ''@mui/material'';\nimport { useSuspenseQuery } from ''@tanstack/react-query'';\nimport { featureApi } from ''../api/featureApi'';\nimport type { FeatureData } from ''~types/feature'';\n\ninterface MyComponentProps {\n    id: number;\n    onAction?: () => void;\n}\n\nexport const MyComponent: React.FC<MyComponentProps> = ({ id, onAction }) => {\n    const [state, setState] = useState<string>('''');\n\n    const { data } = useSuspenseQuery({\n        queryKey: [''feature'', id],\n        queryFn: () => featureApi.getFeature(id),\n    });\n\n    const handleAction = useCallback(() => {\n        setState(''updated'');\n        onAction?.();\n    }, [onAction]);\n\n    return (\n        <Box sx={{ p: 2 }}>\n            <Paper sx={{ p: 3 }}>\n                {/* Content */}\n            </Paper>\n        </Box>\n    );\n};\n\nexport default MyComponent;\n```\n\nFor complete examples, see [resources/complete-examples.md](resources/complete-examples.md)\n\n---\n\n## Related Skills\n\n- **error-tracking**: Error tracking with Sentry (applies to frontend too)\n- **backend-dev-guidelines**: Backend API patterns that frontend consumes\n\n---\n\n**Skill Status**: Modular structure with progressive loading for optimal context management\n"},"lastSynced":"2026-03-04T13:36:13.028Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing comprehensive React development guidelines with Suspense-based data fetching and performance optimization.","zh":"非常适合需要全面React开发指南的全栈代理，包括基于Suspense的数据获取和性能优化。","ja":"Suspenseベースのデータ取得とパフォーマンス最適化を含む包括的なReact開発ガイドラインが必要なフルスタックエージェントに最適です。","ko":"서스펜스 기반 데이터 가져오기 및 성능 최적화를 포함한 포괄적인 리액트 개발 지침이 필요한 풀스택 에이전트에 적합합니다.","es":"Perfecto para Agentes de Full Stack que necesitan pautas de desarrollo de React integrales con extracción de datos basada en Suspense y optimización de rendimiento.","fr":"Parfait pour les agents Full Stack ayant besoin de directives de développement React complètes avec une récupération de données basée sur Suspense et une optimisation des performances.","de":"Perfekt für Full-Stack-Agents, die umfassende React-Entwicklungsrichtlinien mit Suspense-basiertem Datenabruf und Leistungsoptimierung benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de diretrizes abrangentes de desenvolvimento React com busca de dados baseada em Suspense e otimização de desempenho.","ru":"Идеально для полноценных агентов, требующих комплексных руководств по разработке React с помощью Suspense на основе получения данных и оптимизации производительности.","ar":"مثالي لعميل التيار الكامل الذي يحتاج إلى إرشادات شاملة لتطوير React مع استرجاع البيانات القائم على Suspense وتحسين الأداء."},"recommendation":{"en":"Empowers agents to build high-performance React applications using Suspense-based data fetching, lazy loading, and TanStack Query for efficient data management, while also leveraging MUI v7 for styling and TypeScript for best practices.","zh":"赋予代理构建高性能的React应用程序的能力，使用基于Suspense的数据获取、懒加载和TanStack Query进行高效的数据管理，同时利用MUI v7进行样式设计和TypeScript进行最佳实践。","ja":"Suspenseベースのデータ取得、遅延ローディング、TanStack Queryによる効率的なデータ管理を使用して、高パフォーマンスのReactアプリケーションを構築するエージェントの能力を付与し、MUI v7を使用してスタイリングを行い、TypeScriptを使用してベストプラクティスを実現します。","ko":"서스펜스 기반 데이터 가져오기, 지연 로딩 및 TanStack Query를 통한 효율적인 데이터 관리를 사용하여 고성능 리액트 애플리케이션을 구축할 수 있는 에이전트의 능력을 부여하며, MUI v7를 사용하여 스타일을 지정하고, TypeScript를 사용하여 최선의 관행을 구현합니다.","es":"Permite a los agentes crear aplicaciones React de alto rendimiento que utilizan la recuperación de datos basada en Suspense, carga diferida y TanStack Query para una gestión de datos eficiente, y también aprovechan MUI v7 para el estilo y TypeScript para las mejores prácticas.","fr":"Permet aux agents de créer des applications React haute performance utilisant la récupération de données basée sur Suspense, le chargement différé et TanStack Query pour une gestion de données efficace, tout en exploitant MUI v7 pour la mise en page et TypeScript pour les meilleures pratiques.","de":"Ermöglicht es Agenten, hochleistungsstarke React-Anwendungen zu erstellen, die Suspense-basierten Datenabruf, Lazy Loading und TanStack Query für effizientes Datenmanagement verwenden, und auch MUI v7 für die Stilgebung und TypeScript für die besten Praktiken nutzen.","pt":"Habilita os agentes a construir aplicações React de alto desempenho usando busca de dados baseada em Suspense, carregamento lento e TanStack Query para gerenciamento de dados eficiente, aproveitando também o MUI v7 para estilização e TypeScript para as melhores práticas.","ru":"Наделяет агентов возможностью создавать высокопроизводительные приложения React, используя Suspense на основе получения данных, ленивую загрузку и TanStack Query для эффективного управления данными, а также использует MUI v7 для стилизации и TypeScript для соблюдения лучших практик.","ar":"تمكّن الوكلاء من بناء تطبيقات React عالية الأداء باستخدام استرجاع البيانات القائم على Suspense وتحميل متأخر و TanStack Query لإدارة البيانات بفعالية، مع الاستفادة من MUI v7 لأغراض التطوير و TypeScript لتحقيق أفضل الممارسات."},"useCases":{"en":["Building new components or pages with optimized performance","Implementing efficient data fetching with TanStack Query","Setting up routing with TanStack Router for seamless navigation","Optimizing frontend code organization for better maintainability"],"zh":["使用优化的性能构建新的组件或页面","使用TanStack Query实现高效的数据获取","使用TanStack Router设置路由以实现无缝导航","优化前端代码组织以实现更好的可维护性"],"ja":["最適化されたパフォーマンスで新しいコンポーネントまたはページを構築する","TanStack Queryを使用して効率的なデータ取得を実現する","TanStack Routerを使用してルーティングを設定し、シームレスなナビゲーションを実現する","フロントエンドコードの組織を最適化して、保守性を向上させる"],"ko":["최적화된 성능으로 새로운 컴포넌트 또는 페이지를 구축하는 것","TanStack Query를 사용하여 효율적인 데이터 가져오기를 구현하는 것","TanStack Router를 사용하여 라우팅을 설정하고 무결점 탐색을 구현하는 것","프론트엔드 코드의 구성최적화를 통해 유지 관리성을 향상시키는 것"],"es":["Creación de nuevos componentes o páginas con rendimiento optimizado","Implementación de una recuperación de datos eficiente con TanStack Query","Configuración de enrutamiento con TanStack Router para una navegación sin problemas","Optimización de la organización de código frontend para una mejor mantenibilidad"],"fr":["Création de nouveaux composants ou pages avec des performances optimisées","Mise en œuvre d''une récupération de données efficace avec TanStack Query","Configuration du routage avec TanStack Router pour une navigation sans interruption","Optimisation de l''organisation du code frontend pour une meilleure maintenabilité"],"de":["Erstellung neuer Komponenten oder Seiten mit optimiertem Leistungsverhalten","Implementierung eines effizienten Datenabrufs mit TanStack Query","Einrichtung der Routing-Konfiguration mit TanStack Router für eine nahtlose Navigation","Optimierung der Frontend-Code-Organisation für eine bessere Wartbarkeit"],"pt":["Construir novos componentes ou páginas com desempenho otimizado","Implementar busca de dados eficiente com TanStack Query","Configurar roteamento com TanStack Router para navegação sem interrupção","Otimizar organização de código frontend para melhor manutenibilidade"],"ru":["Создание новых компонентов или страниц с оптимизированной производительностью","Реализация эффективного получения данных с помощью TanStack Query","Настройка маршрутизации с помощью TanStack Router для бесшовной навигации","Оптимизация организации frontend-кода для лучшей поддержки"],"ar":["بناء مكونات أو صفحات جديدة مع أداء محسّن","تطبيق استرجاع البيانات بفعالية مع TanStack Query","ضبط التوجيه مع TanStack Router من أجل التنقل السلس","تحسين تنظيم代码 الجانب الأمامي لتحقيق صيانة أفضل"]},"limitations":{"en":["Requires React and TypeScript setup","Limited to frontend development with React","Dependent on TanStack Query and MUI v7 libraries"],"zh":["需要React和TypeScript设置","仅限于使用React的前端开发","依赖于TanStack Query和MUI v7库"],"ja":["ReactとTypeScriptの設定が必要","Reactを使用したフロントエンド開発に限定される","TanStack QueryとMUI v7ライブラリに依存する"],"ko":["리액트 및 타입스크립트 설정이 필요","리액트를 사용한 프론트엔드 개발에 한정","TanStack Query 및 MUI v7 라이브러리에 의존"],"es":["Requiere configuración de React y TypeScript","Limitado al desarrollo frontend con React","Dependiente de las bibliotecas TanStack Query y MUI v7"],"fr":["Nécessite une configuration React et TypeScript","Limité au développement frontend avec React","Dépendant des bibliothèques TanStack Query et MUI v7"],"de":["Benötigt React- und TypeScript-Konfiguration","Begrenzt auf die Frontend-Entwicklung mit React","Abhängig von den Bibliotheken TanStack Query und MUI v7"],"pt":["Requer configuração do React e TypeScript","Limitado ao desenvolvimento frontend com React","Dependente das bibliotecas TanStack Query e MUI v7"],"ru":["Требует настройки React и TypeScript","Ограничен разработкой frontend с помощью React","Зависит от библиотек TanStack Query и MUI v7"],"ar":["يتطلب إعداد React و TypeScript","محدود بالتطوير الجانبي الأمامي مع React","يعتمد على مكتبات TanStack Query و MUI v7"]},"version":3},"contentHash":"e8187169648aa60b3828fde643b0046a343cff7984887e40c3966c791efcc7c8","qualityScore":49}');
