INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maminul007/trading-platform/alpha-decay', 'alpha-decay', 'maminul007', 'trading-platform', 'community', 'alpha-decay maminul007 trading-platform community alpha-decay 是 Algotradingstudio 中的一种 AI 代理技术，用于提升开发效率 alpha-decay は Algotradingstudio の AI エージェント機能で、開発を最適化します alpha-decay는 Algotradingstudio의 AI 에이전트 기능으로 개발 능력을 최적화합니다 Alpha-decay es una herramienta de IA para Algotradingstudio que ofrece funcionalidades avanzadas para el trading automático Alpha-decay est un outil IA pour Algotradingstudio qui offre des fonctionnalités avancées pour le trading automatique Alpha-decay ist ein KI-Tool für Algotradingstudio, das erweiterte Funktionen für den automatischen Handel bietet O alpha-decay é uma ferramenta de IA para Algotradingstudio que melhora a precisão das negociações ИИ Агент alpha-decay для Algotradingstudio повышает точность торговли أداة الذكاء الاصطناعي alpha-decay لمنصة Algotradingstudio تحسن دقة الصفقات Algotradingstudio alpha-decay 介绍 Algotradingstudio 教程 AI 代理技术 开发工具比较 alpha-decay 安装 开发效率优化 交易策略优化 Algotradingstudio 代替品 Algotradingstudio');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pythoninthegrasses/lunchjs/discover-zig', 'community', 'pythoninthegrasses', 'lunchjs', 'pythoninthegrasses/lunchjs', 'discover-zig', 0, 0, 49, '2026-03-04T13:07:01.730Z', '2026-03-04T13:59:10.222Z', 'a8eee673a13f10abfda7b0325808ae7698044404b2abe685ca8c716f51d5bc7c', '{"id":"pythoninthegrasses/lunchjs/discover-zig","name":"discover-zig","description":{"zh":"discover-zig 是一个帮助您发现新餐饮选择的 AI 工具，使用 React 和 Node.js 构建","ja":"discover-zig は、React と Node.js で構築された新しい食事の選択肢を発見するための AI エージェントです","ko":"discover-zig 는 React 와 Node.js 로 구축된 새로운 식사 선택을 발견하는 AI 에이전트입니다","es":"Descubre Zig, una herramienta de inteligencia artificial que ayuda a los desarrolladores a encontrar soluciones creativas para problemas cotidianos como ¿qué hay para almorzar?","fr":"Découvrez Zig, un outil d''intelligence artificielle qui aide les développeurs à trouver des solutions créatives pour les problèmes quotidiens tels que ¿qué manger pour déjeuner?","de":"Entdecken Sie Zig, ein KI-Tool, das Entwicklern hilft, kreative Lösungen für alltägliche Probleme wie ¿was gibt es zum Mittagessen? zu finden","pt":"O discover-zig é uma ferramenta de IA que ajuda desenvolvedores a descobrir novas tecnologias e melhorar sua produtividade","ru":"ИИ Агент discover-zig помогает разработчикам открывать новые технологии и повышать производительность","ar":"أداة الذكاء الاصطناعي discover-zig تساعد المطورين على اكتشاف تقنيات جديدة وتحسين إنتاجيتهم","en":"What''s for lunch??"},"seo":{"title":{"zh":"发现 Zig AI 工具 - discover-zig","ja":"AIエージェント discover-zig を使ってみよう","ko":"discover-zig AI 에이전트를 사용해 보세요","es":"Herramientas de AI: Descubre Zig para desarrolladores","fr":"Outils d''IA : Découvrez Zig pour les développeurs","de":"AI-Tools: Entdecken Sie Zig für Entwickler","pt":"Descubra Ferramentas de IA com discover-zig","ru":"ИИ Агенты: discover-zig для разработчико