INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('unkeyed/unkey/reviewing-restate-handlers', 'reviewing-restate-handlers', 'unkeyed', 'unkey', 'community', 'reviewing-restate-handlers unkeyed unkey community Reviewing Restate Handlers是现代API开发平台的AI智能代理，帮助开发者提高开发效率 Reviewing Restate Handlersは、モダンAPI開発プラットフォームのAIエージェントです Reviewing Restate Handlers는 현대적인 API 개발 플랫폼을 위한 AI 에이전트입니다 La plataforma de desarrollador para APIs modernas con reviewing-restate-handlers ofrece una forma eficiente de gestionar APIs La plateforme de développement pour les API modernes avec reviewing-restate-handlers offre un moyen efficace de gérer les API Die Entwicklerplattform für moderne APIs mit reviewing-restate-handlers bietet eine effiziente Möglichkeit, APIs zu verwalten O Reviewing Restate Handlers é uma plataforma de desenvolvimento para APIs modernas, permitindo a criação de soluções personalizadas Reviewing Restate Handlers - это платформа для разработки современных API, позволяющая создавать индивидуальные решения مراجعة إعادة تحديد المحتوى هي منصة تطوير للمواقع المتقدمة، تمكن من إنشاء حلول مخصصة The Developer Platform for Modern APIs AI智能代理 现代API开发 开发效率 开发工具 编程语言 开发文档 开发团队 如何使用Reviewing Restate Handlers Reviewing Restate Handlers安装 Reviewing Restate Handlers设置指南 The Developer Platform for Modern APIs');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('settlemint/agent-marketplace/rams', 'community', 'settlemint', 'agent-marketplace', 'settlemint/agent-marketplace', 'rams', 0, 0, 49, '2026-03-04T13:07:01.737Z', '2026-03-04T14:03:25.129Z', '32283f528a523645642acd8c3fc74df28fb5080670a2991b596917e884b56002', '{"id":"settlemint/agent-marketplace/rams","name":"rams","description":{"zh":"rams提供SettleMint代理编排和开发工具，帮助开发者高效构建AI应用","ja":"ramsはSettleMintエージェントオーケストレーションと開発ツールを提供し、開発者が効率的にAIアプリケーションを構築できるようにします","ko":"rams는 SettleMint 에이전트 구축 및 개발 도구를 제공하여 개발자가 효율적으로 AI 애플리케이션을 구축할 수 있도록 합니다","es":"SettleMint ofrece herramientas de orquestación y desarrollo de agentes para mejorar la eficiencia de tus proyectos de AI Agentes","fr":"SettleMint propose des outils d''orchestration et de développement d''agents pour améliorer l''efficacité de vos projets d''agents IA","de":"SettleMint bietet Agenten-Orchestrierungs- und Entwicklungstools, um die Effizienz Ihrer KI-Agenten-Projekte zu verbessern","pt":"Rams é uma plataforma de orquestração e desenvolvimento de agentes de IA, oferecendo ferramentas para melhorar a produtividade.","ru":"Rams - это платформа оркестровки и разработки ИИ агентов, предлагающая инструменты для повышения производительности.","ar":"رامز هي منصة توجيه وتطوير للوكلاء الذكية، تقدم أدوات لتحسين الإنتاجية.","en":"SettleMint agent orchestration and development tools"},"seo":{"title":{"zh":"rams AI工具 - SettleMint 代理编排与开发","ja":"rams AIエージェント - SettleMint エージェントオーケストレーションと開発ツール","ko":"rams AI 에이전트 - SettleMint 에이전트 구축 및 개발 도구","es":"Herramientas de orquestación y desarrollo de agentes de S...","fr":"Outils d''orchestration et de développement d''agents Settl...","de":"SettleMint-Agenten-Orchestrierungs- und Entwicklungstools","pt":"Ferramentas de Orquestração de Agentes de IA - Rams","ru":"ИИ Агенты: Инструменты оркестровки SettleMint - Rams","ar":"أدوات