INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('darthmolen/EnglishConnect/regenerate-example', 'regenerate-example', 'darthmolen', 'EnglishConnect', 'community', 'regenerate-example darthmolen EnglishConnect community regenerate-example AI智能工具是用于教学英语作为第二语言的工具，使用React和Python等技术 regenerate-example AIエージェントは、英語を第二言語として教えるためのツールで、ReactやPythonなどの技術を使用 regenerate-example AI 에이전트는 영어를 두번째 언어로 가르치기 위한 도구로, React와 Python 등의 기술을 사용 El skill ''regenerate-example'' utiliza inteligencia artificial para enseñar inglés como segunda lengua de manera interactiva y personalizada Le skill ''regenerate-example'' utilise l''intelligence artificielle pour enseigner l''anglais comme deuxième langue de manière interactive et personnalisée Der Skill ''regenerate-example'' nutzt KI, um Englisch als zweite Sprache interaktiv und personalisiert zu unterrichten As ferramentas de IA podem ajudar no ensino de inglês como segunda língua, oferecendo recursos personalizados e interativos ИИ Агенты могут помочь в обучении английскому как второму языку, предоставляя персонализированные и интерактивные ресурсы أدوات الذكاء الاصطناعي يمكن أن تساعد في تعليم اللغة الإنجليزية كلغة ثانية، وتقديم موارد مخصصة وتفاعلية Teaching English as a second language 如何使用regenerate-example 什么是AI智能工具 regenerate-example替代品 regenerate-example vs 其他AI工具 regenerate-example安装 regenerate-example设置指南 教学英语作为第二语言 AI智能工具教程 Teaching English as a second language');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('miethe/codebase-map/d3-viz', 'community', 'miethe', 'codebase-map', 'miethe/codebase-map', 'd3-viz', 0, 0, 49, '2026-03-04T13:07:01.779Z', '2026-03-04T14:24:05.855Z', '4b1f820cd87c55dc6b7c714a76c1320903187967cd43f3b4db9d6eacbcc085b3', '{"id":"miethe/codebase-map/d3-viz","name":"d3-viz","description":{"zh":"D3-Viz是一种AI智能工具，提供各种视图来可视化代码库和代码流","ja":"D3-Vizは、コードベースとコードフローを可視化するためのAIエージェントです。様々なビューでコードを可視化します","ko":"D3-Viz는 코드베이스와 코드 흐름을 시각화하는 AI 에이전트로, 다양한 뷰를 제공합니다","es":"d3-viz es una herramienta de visualización de código que te permite ver tus flujos de código de manera clara","fr":"d3-viz est un outil de visualisation de code qui vous permet de voir vos flux de code de manière claire","de":"d3-viz ist ein Code-Visualisierungstool, das es Ihnen ermöglicht, Ihre Codeflüsse klar zu sehen","pt":"Visualize sua base de código e todos os fluxos de código com vistas variadas usando d3-viz","ru":"Визуализируйте свою кодовую базу и все кодовые потоки с различными видами, используя d3-viz","ar":"استكشف قاعدة الشفرة الخاصة بك وجميع تدفقات الشفرة مع مناظير متعددة باستخدام d3-viz","en":"Visualize your codebase and all code flows with various views."},"seo":{"title":{"zh":"D3-Viz AI智能工具 - 可视化代码库和代码流","ja":"D3-Viz AIエージェント - コードベースとコードフローを可視化","ko":"D3-Viz AI 에이전트 - 코드베이스와 코드 흐름 시각화","es":"Herramientas de visualización de código con d3-viz","fr":"Outils de visualisation de code avec d3-viz","de":"Code-Visualisierungstools mit d3-viz","pt":"Ferramentas de Visualização de Código com d3-viz","ru":"ИИ Агенты: Визуализация Кодовой Базы с d3-viz","ar":"أدوات التعمق في الشفرة مع d3-viz","en":"d3-viz"},"description":{"zh":"D3-Viz是一种AI智能工具，提供各种视图来可视化代码库和代码流","ja":"D3-Vizは、コードベースとコードフローを可視化するためのAIエージェントです。様々なビューでコードを可視化します","ko":"D3-Viz는 코드베이스와 코드 흐름을 시각화하는 AI 에이전트로, 다양한 뷰를 제공합니다","es":"d3-viz es una herramienta de visualización de código que te permite ver tus flujos de código de manera clara","fr":"d3-viz est un outil de visualisation de code qui vous permet de voir vos flux de code de manière claire","de":"d3-viz ist ein Code-Visualisierungstool, das es Ihnen ermöglicht, Ihre Codeflüsse klar zu sehen","pt":"Visualize sua base de código e todos os fluxos de código com vistas variadas usando d3-viz","ru":"Визуализируйте свою кодовую базу и все кодовые потоки с различными видами, используя d3-viz","ar":"استكشف قاعدة الشفرة الخاصة بك وجميع تدفقات الشفرة مع مناظير متعددة باستخدام d3-viz","en":"Visualize your codebase and all code flows with various views."},"definition":{"en":"Visualize your codebase and all code flows with various views."},"features":{"zh":["可视化代码库和代码流","提供各种视图来展示代码结构","支持多种编程语言","提高开发效率和代码质量","易于使用和集成"],"ja":["コードベースとコードフローを可視化","コード構造を様々なビューで表示","多くのプログラミング言語をサポート","開発効率とコード品質を向上","簡単に使用し、統合する"],"ko":["코드베이스와 코드 흐름을 시각화","코드 구조를 다양한 뷰로 표시","여러 프로그래밍 언어를 지원","개발 효율성과 코드 품질을 향상","쉽게 사용하고 통합하기"],"es":["Visualización de flujos de código","Vistas variadas para una mejor comprensión","Mejora de la productividad","Integración con herramientas de desarrollo","Personalización de la visualización"],"fr":["Visualisation des flux de code","Vues variées pour une meilleure compréhension","Amélioration de la productivité","Intégration avec les outils de développement","Personnalisation de la visualisation"],"de":["Visualisierung von Codeflüssen","Verschiedene Ansichten für ein besseres Verständnis","Steigerung der Produktivität","Integration mit Entwicklungstools","Anpassung der Visualisierung"],"pt":["Visualização de fluxos de código","Vistas variadas para entender a base de código","Melhoria da produtividade com insights claros","Integração com ferramentas de desenvolvimento populares","Personalização de layouts e designs"],"ru":["Визуализация кодовых потоков","Различные виды для понимания кодовой базы","Повышение производительности с ясными инсайтами","Интеграция с популярными инструментами разработки","Настройка макетов и дизайнов"],"ar":["تعمق تدفقات الشفرة","مناظير متعددة لفهم قاعدة الشفرة","زيادة الإنتاجية مع رؤى واضحة","التكامل مع أدوات التطوير الشهيرة","تخصيص التخطيطات والتصاميم"]},"keywords":{"zh":["如何使用D3-Viz","什么是D3-Viz","D3-Viz替代品","D3-Viz安装","D3-Viz设置指南","代码可视化工具","AI智能工具","代码流可视化"],"ja":["D3-Vizの使い方","D3-Vizとは","D3-Vizの代替","D3-Vizのインストール","D3-Vizの設定ガイド","コード可視化ツール","AIエージェント","コードフローキャプチャ"],"ko":["D3-Viz 사용법","D3-Viz란","D3-Viz 대체품","D3-Viz 설치","D3-Viz 설정 가이드","코드 시각화 도구","AI 에이전트","코드 흐름 시각화"],"es":["herramientas de visualización de código","d3-viz","cómo usar d3-viz","alternativas a d3-viz","d3-viz vs graphviz","instalación de d3-viz","guía de configuración de d3-viz","visualización de código en javascript","herramientas de desarrollo de software"],"fr":["outils de visualisation de code","d3-viz","comment utiliser d3-viz","alternatives à d3-viz","d3-viz vs graphviz","installation de d3-viz","guide de configuration de d3-viz","visualisation de code en javascript","outils de développement de logiciels"],"de":["Code-Visualisierungstools","d3-viz","wie man d3-viz verwendet","alternativen zu d3-viz","d3-viz vs graphviz","installation von d3-viz","konfigurationsanleitung für d3-viz","code-visualisierung in javascript","entwicklungstools für software"],"pt":["como usar d3-viz","o que é d3-viz","ferramentas de visualização de código","d3-viz vs graphviz","instalar d3-viz","guia de configuração do d3-viz","alternativas ao d3-viz"],"ru":["как использовать d3-viz","что такое d3-viz","инструменты визуализации кода","d3-viz vs graphviz","установить d3-viz","руководство по настройке d3-viz","альтернативы d3-viz"],"ar":["كيفية استخدام d3-viz","ما هو d3-viz","أدوات تعميق الشفرة","d3-viz مقابل graphviz","تثبيت d3-viz","دليل إعداد d3-viz","بديل d3-viz"]}},"owner":"miethe","repo":"codebase-map","repoPath":"miethe/codebase-map","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.779Z","topics":[],"category":"community","skillMd":{"name":"d3-viz","description":"Creating interactive data visualisations using d3.js. This skill should be used when creating custom charts, graphs, network diagrams, geographic visualisations, or any complex SVG-based data visualisation that requires fine-grained control over visual elements, transitions, or interactions. Use this for bespoke visualisations beyond standard charting libraries, whether in React, Vue, Svelte, vanilla JavaScript, or any other environment.","bodyPreview":"# D3.js Visualisation\n\n## Overview\n\nThis skill provides guidance for creating sophisticated, interactive data visualisations using d3.js. D3.js (Data-Driven Documents) excels at binding data to DOM elements and applying data-driven transformations to create custom, publication-quality visualisations with precise control over every visual element. The techniques work across any JavaScript environment, including vanilla JavaScript, React, Vue, Svelte, and other frameworks.\n\n## When to use d3.js\n\n*","body":"# D3.js Visualisation\n\n## Overview\n\nThis skill provides guidance for creating sophisticated, interactive data visualisations using d3.js. D3.js (Data-Driven Documents) excels at binding data to DOM elements and applying data-driven transformations to create custom, publication-quality visualisations with precise control over every visual element. The techniques work across any JavaScript environment, including vanilla JavaScript, React, Vue, Svelte, and other frameworks.\n\n## When to use d3.js\n\n**Use d3.js for:**\n- Custom visualisations requiring unique visual encodings or layouts\n- Interactive explorations with complex pan, zoom, or brush behaviours\n- Network/graph visualisations (force-directed layouts, tree diagrams, hierarchies, chord diagrams)\n- Geographic visualisations with custom projections\n- Visualisations requiring smooth, choreographed transitions\n- Publication-quality graphics with fine-grained styling control\n- Novel chart types not available in standard libraries\n\n**Consider alternatives for:**\n- 3D visualisations - use Three.js instead\n\n## Core workflow\n\n### 1. Set up d3.js\n\nImport d3 at the top of your script:\n\n```javascript\nimport * as d3 from ''d3'';\n```\n\nOr use the CDN version (7.x):\n\n```html\n<script src=\"https://d3js.org/d3.v7.min.js\"></script>\n```\n\nAll modules (scales, axes, shapes, transitions, etc.) are accessible through the `d3` namespace.\n\n### 2. Choose the integration pattern\n\n**Pattern A: Direct DOM manipulation (recommended for most cases)**\nUse d3 to select DOM elements and manipulate them imperatively. This works in any JavaScript environment:\n\n```javascript\nfunction drawChart(data) {\n  if (!data || data.length === 0) return;\n\n  const svg = d3.select(''#chart''); // Select by ID, class, or DOM element\n\n  // Clear previous content\n  svg.selectAll(\"*\").remove();\n\n  // Set up dimensions\n  const width = 800;\n  const height = 400;\n  const margin = { top: 20, right: 30, bottom: 40, left: 50 };\n\n  // Create scales, axes, and draw visualisation\n  // ... d3 code here ...\n}\n\n// Call when data changes\ndrawChart(myData);\n```\n\n**Pattern B: Declarative rendering (for frameworks with templating)**\nUse d3 for data calculations (scales, layouts) but render elements via your framework:\n\n```javascript\nfunction getChartElements(data) {\n  const xScale = d3.scaleLinear()\n    .domain([0, d3.max(data, d => d.value)])\n    .range([0, 400]);\n\n  return data.map((d, i) => ({\n    x: 50,\n    y: i * 30,\n    width: xScale(d.value),\n    height: 25\n  }));\n}\n\n// In React: {getChartElements(data).map((d, i) => <rect key={i} {...d} fill=\"steelblue\" />)}\n// In Vue: v-for directive over the returned array\n// In vanilla JS: Create elements manually from the returned data\n```\n\nUse Pattern A for complex visualisations with transitions, interactions, or when leveraging d3''s full capabilities. Use Pattern B for simpler visualisations or when your framework prefers declarative rendering.\n\n### 3. Structure the visualisation code\n\nFollow this standard structure in your drawing function:\n\n```javascript\nfunction drawVisualization(data) {\n  if (!data || data.length === 0) return;\n\n  const svg = d3.select(''#chart''); // Or pass a selector/element\n  svg.selectAll(\"*\").remove(); // Clear previous render\n\n  // 1. Define dimensions\n  const width = 800;\n  const height = 400;\n  const margin = { top: 20, right: 30, bottom: 40, left: 50 };\n  const innerWidth = width - margin.left - margin.right;\n  const innerHeight = height - margin.top - margin.bottom;\n\n  // 2. Create main group with margins\n  const g = svg.append(\"g\")\n    .attr(\"transform\", `translate(${margin.left},${margin.top})`);\n\n  // 3. Create scales\n  const xScale = d3.scaleLinear()\n    .domain([0, d3.max(data, d => d.x)])\n    .range([0, innerWidth]);\n\n  const yScale = d3.scaleLinear()\n    .domain([0, d3.max(data, d => d.y)])\n    .range([innerHeight, 0]); // Note: inverted for SVG coordinates\n\n  // 4. Create and append axes\n  const xAxis = d3.axisBottom(xScale);\n  const yAxis = d3.axisLeft(yScale);\n\n  g.append(\"g\")\n    .attr(\"transform\", `translate(0,${innerHeight})`)\n    .call(xAxis);\n\n  g.append(\"g\")\n    .call(yAxis);\n\n  // 5. Bind data and create visual elements\n  g.selectAll(\"circle\")\n    .data(data)\n    .join(\"circle\")\n    .attr(\"cx\", d => xScale(d.x))\n    .attr(\"cy\", d => yScale(d.y))\n    .attr(\"r\", 5)\n    .attr(\"fill\", \"steelblue\");\n}\n\n// Call when data changes\ndrawVisualization(myData);\n```\n\n### 4. Implement responsive sizing\n\nMake visualisations responsive to container size:\n\n```javascript\nfunction setupResponsiveChart(containerId, data) {\n  const container = document.getElementById(containerId);\n  const svg = d3.select(`#${containerId}`).append(''svg'');\n\n  function updateChart() {\n    const { width, height } = container.getBoundingClientRect();\n    svg.attr(''width'', width).attr(''height'', height);\n\n    // Redraw visualisation with new dimensions\n    drawChart(data, svg, width, height);\n  }\n\n  // Update on initial load\n  updateChart();\n\n  // Update on window resize\n  window.addEventListener(''resize'', updateChart);\n\n  // Return cleanup function\n  return () => window.removeEventListener(''resize'', updateChart);\n}\n\n// Usage:\n// const cleanup = setupResponsiveChart(''chart-container'', myData);\n// cleanup(); // Call when component unmounts or element removed\n```\n\nOr use ResizeObserver for more direct container monitoring:\n\n```javascript\nfunction setupResponsiveChartWithObserver(svgElement, data) {\n  const observer = new ResizeObserver(() => {\n    const { width, height } = svgElement.getBoundingClientRect();\n    d3.select(svgElement)\n      .attr(''width'', width)\n      .attr(''height'', height);\n\n    // Redraw visualisation\n    drawChart(data, d3.select(svgElement), width, height);\n  });\n\n  observer.observe(svgElement.parentElement);\n  return () => observer.disconnect();\n}\n```\n\n## Common visualisation patterns\n\n### Bar chart\n\n```javascript\nfunction drawBarChart(data, svgElement) {\n  if (!data || data.length === 0) return;\n\n  const svg = d3.select(svgElement);\n  svg.selectAll(\"*\").remove();\n\n  const width = 800;\n  const height = 400;\n  const margin = { top: 20, right: 30, bottom: 40, left: 50 };\n  const innerWidth = width - margin.left - margin.right;\n  const innerHeight = height - margin.top - margin.bottom;\n\n  const g = svg.append(\"g\")\n    .attr(\"transform\", `translate(${margin.left},${margin.top})`);\n\n  const xScale = d3.scaleBand()\n    .domain(data.map(d => d.category))\n    .range([0, innerWidth])\n    .padding(0.1);\n\n  const yScale = d3.scaleLinear()\n    .domain([0, d3.max(data, d => d.value)])\n    .range([innerHeight, 0]);\n\n  g.append(\"g\")\n    .attr(\"transform\", `translate(0,${innerHeight})`)\n    .call(d3.axisBottom(xScale));\n\n  g.append(\"g\")\n    .call(d3.axisLeft(yScale));\n\n  g.selectAll(\"rect\")\n    .data(data)\n    .join(\"rect\")\n    .attr(\"x\", d => xScale(d.category))\n    .attr(\"y\", d => yScale(d.value))\n    .attr(\"width\", xScale.bandwidth())\n    .attr(\"height\", d => innerHeight - yScale(d.value))\n    .attr(\"fill\", \"steelblue\");\n}\n\n// Usage:\n// drawBarChart(myData, document.getElementById(''chart''));\n```\n\n### Line chart\n\n```javascript\nconst line = d3.line()\n  .x(d => xScale(d.date))\n  .y(d => yScale(d.value))\n  .curve(d3.curveMonotoneX); // Smooth curve\n\ng.append(\"path\")\n  .datum(data)\n  .attr(\"fill\", \"none\")\n  .attr(\"stroke\", \"steelblue\")\n  .attr(\"stroke-width\", 2)\n  .attr(\"d\", line);\n```\n\n### Scatter plot\n\n```javascript\ng.selectAll(\"circle\")\n  .data(data)\n  .join(\"circle\")\n  .attr(\"cx\", d => xScale(d.x))\n  .attr(\"cy\", d => yScale(d.y))\n  .attr(\"r\", d => sizeScale(d.size)) // Optional: size encoding\n  .attr(\"fill\", d => colourScale(d.category)) // Optional: colour encoding\n  .attr(\"opacity\", 0.7);\n```\n\n### Chord diagram\n\nA chord diagram shows relationships between entities in a circular layout, with ribbons representing flows between them:\n\n```javascript\nfunction drawChordDiagram(data) {\n  // data format: array of objects with source, target, and value\n  // Example: [{ source: ''A'', target: ''B'', value: 10 }, ...]\n\n  if (!data || data.length === 0) return;\n\n  const svg = d3.select(''#chart'');\n  svg.selectAll(\"*\").remove();\n\n  const width = 600;\n  const height = 600;\n  const innerRadius = Math.min(width, height) * 0.3;\n  const outerRadius = innerRadius + 30;\n\n  // Create matrix from data\n  const nodes = Array.from(new Set(data.flatMap(d => [d.source, d.target])));\n  const matrix = Array.from({ length: nodes.length }, () => Array(nodes.length).fill(0));\n\n  data.forEach(d => {\n    const i = nodes.indexOf(d.source);\n    const j = nodes.indexOf(d.target);\n    matrix[i][j] += d.value;\n    matrix[j][i] += d.value;\n  });\n\n  // Create chord layout\n  const chord = d3.chord()\n    .padAngle(0.05)\n    .sortSubgroups(d3.descending);\n\n  const arc = d3.arc()\n    .innerRadius(innerRadius)\n    .outerRadius(outerRadius);\n\n  const ribbon = d3.ribbon()\n    .source(d => d.source)\n    .target(d => d.target);\n\n  const colourScale = d3.scaleOrdinal(d3.schemeCategory10)\n    .domain(nodes);\n\n  const g = svg.append(\"g\")\n    .attr(\"transform\", `translate(${width / 2},${height / 2})`);\n\n  const chords = chord(matrix);\n\n  // Draw ribbons\n  g.append(\"g\")\n    .attr(\"fill-opacity\", 0.67)\n    .selectAll(\"path\")\n    .data(chords)\n    .join(\"path\")\n    .attr(\"d\", ribbon)\n    .attr(\"fill\", d => colourScale(nodes[d.source.index]))\n    .attr(\"stroke\", d => d3.rgb(colourScale(nodes[d.source.index])).darker());\n\n  // Draw groups (arcs)\n  const group = g.append(\"g\")\n    .selectAll(\"g\")\n    .data(chords.groups)\n    .join(\"g\");\n\n  group.append(\"path\")\n    .attr(\"d\", arc)\n    .attr(\"fill\", d => colourScale(nodes[d.index]))\n    .attr(\"stroke\", d => d3.rgb(colourScale(nodes[d.index])).darker());\n\n  // Add labels\n  group.append(\"text\")\n    .each(d => { d.angle = (d.startAngle + d.endAngle) / 2; })\n    .attr(\"dy\", \"0.31em\")\n    .attr(\"transform\", d => `rotate(${(d.angle * 180 / Math.PI) - 90})translate(${outerRadius + 30})${d.angle > Math.PI ? \"rotate(180)\" : \"\"}`)\n    .attr(\"text-anchor\", d => d.angle > Math.PI ? \"end\" : null)\n    .text((d, i) => nodes[i])\n    .style(\"font-size\", \"12px\");\n}\n```\n\n### Heatmap\n\nA heatmap uses colour to encode values in a two-dimensional grid, useful for showing patterns across categories:\n\n```javascript\nfunction drawHeatmap(data) {\n  // data format: array of objects with row, column, and value\n  // Example: [{ row: ''A'', column: ''X'', value: 10 }, ...]\n\n  if (!data || data.length === 0) return;\n\n  const svg = d3.select(''#chart'');\n  svg.selectAll(\"*\").remove();\n\n  const width = 800;\n  const height = 600;\n  const margin = { top: 100, right: 30, bottom: 30, left: 100 };\n  const innerWidth = width - margin.left - margin.right;\n  const innerHeight = height - margin.top - margin.bottom;\n\n  // Get unique rows and columns\n  const rows = Array.from(new Set(data.map(d => d.row)));\n  const columns = Array.from(new Set(data.map(d => d.column)));\n\n  const g = svg.append(\"g\")\n    .attr(\"transform\", `translate(${margin.left},${margin.top})`);\n\n  // Create scales\n  const xScale = d3.scaleBand()\n    .domain(columns)\n    .range([0, innerWidth])\n    .padding(0.01);\n\n  const yScale = d3.scaleBand()\n    .domain(rows)\n    .range([0, innerHeight])\n    .padding(0.01);\n\n  // Colour scale for values\n  const colourScale = d3.scaleSequential(d3.interpolateYlOrRd)\n    .domain([0, d3.max(data, d => d.value)]);\n\n  // Draw rectangles\n  g.selectAll(\"rect\")\n    .data(data)\n    .join(\"rect\")\n    .attr(\"x\", d => xScale(d.column))\n    .attr(\"y\", d => yScale(d.row))\n    .attr(\"width\", xScale.bandwidth())\n    .attr(\"height\", yScale.bandwidth())\n    .attr(\"fill\", d => colourScale(d.value));\n\n  // Add x-axis labels\n  svg.append(\"g\")\n    .attr(\"transform\", `translate(${margin.left},${margin.top})`)\n    .selectAll(\"text\")\n    .data(columns)\n    .join(\"text\")\n    .attr(\"x\", d => xScale(d) + xScale.bandwidth() / 2)\n    .attr(\"y\", -10)\n    .attr(\"text-anchor\", \"middle\")\n    .text(d => d)\n    .style(\"font-size\", \"12px\");\n\n  // Add y-axis labels\n  svg.append(\"g\")\n    .attr(\"transform\", `translate(${margin.left},${margin.top})`)\n    .selectAll(\"text\")\n    .data(rows)\n    .join(\"text\")\n    .attr(\"x\", -10)\n    .attr(\"y\", d => yScale(d) + yScale.bandwidth() / 2)\n    .attr(\"dy\", \"0.35em\")\n    .attr(\"text-anchor\", \"end\")\n    .text(d => d)\n    .style(\"font-size\", \"12px\");\n\n  // Add colour legend\n  const legendWidth = 20;\n  const legendHeight = 200;\n  const legend = svg.append(\"g\")\n    .attr(\"transform\", `translate(${width - 60},${margin.top})`);\n\n  const legendScale = d3.scaleLinear()\n    .domain(colourScale.domain())\n    .range([legendHeight, 0]);\n\n  const legendAxis = d3.axisRight(legendScale)\n    .ticks(5);\n\n  // Draw colour gradient in legend\n  for (let i = 0; i < legendHeight; i++) {\n    legend.append(\"rect\")\n      .attr(\"y\", i)\n      .attr(\"width\", legendWidth)\n      .attr(\"height\", 1)\n      .attr(\"fill\", colourScale(legendScale.invert(i)));\n  }\n\n  legend.append(\"g\")\n    .attr(\"transform\", `translate(${legendWidth},0)`)\n    .call(legendAxis);\n}\n```\n\n### Pie chart\n\n```javascript\nconst pie = d3.pie()\n  .value(d => d.value)\n  .sort(null);\n\nconst arc = d3.arc()\n  .innerRadius(0)\n  .outerRadius(Math.min(width, height) / 2 - 20);\n\nconst colourScale = d3.scaleOrdinal(d3.schemeCategory10);\n\nconst g = svg.append(\"g\")\n  .attr(\"transform\", `translate(${width / 2},${height / 2})`);\n\ng.selectAll(\"path\")\n  .data(pie(data))\n  .join(\"path\")\n  .attr(\"d\", arc)\n  .attr(\"fill\", (d, i) => colourScale(i))\n  .attr(\"stroke\", \"white\")\n  .attr(\"stroke-width\", 2);\n```\n\n### Force-directed network\n\n```javascript\nconst simulation = d3.forceSimulation(nodes)\n  .force(\"link\", d3.forceLink(links).id(d => d.id).distance(100))\n  .force(\"charge\", d3.forceManyBody().strength(-300))\n  .force(\"center\", d3.forceCenter(width / 2, height / 2));\n\nconst link = g.selectAll(\"line\")\n  .data(links)\n  .join(\"line\")\n  .attr(\"stroke\", \"#999\")\n  .attr(\"stroke-width\", 1);\n\nconst node = g.selectAll(\"circle\")\n  .data(nodes)\n  .join(\"circle\")\n  .attr(\"r\", 8)\n  .attr(\"fill\", \"steelblue\")\n  .call(d3.drag()\n    .on(\"start\", dragstarted)\n    .on(\"drag\", dragged)\n    .on(\"end\", dragended));\n\nsimulation.on(\"tick\", () => {\n  link\n    .attr(\"x1\", d => d.source.x)\n    .attr(\"y1\", d => d.source.y)\n    .attr(\"x2\", d => d.target.x)\n    .attr(\"y2\", d => d.target.y);\n  \n  node\n    .attr(\"cx\", d => d.x)\n    .attr(\"cy\", d => d.y);\n});\n\nfunction dragstarted(event) {\n  if (!event.active) simulation.alphaTarget(0.3).restart();\n  event.subject.fx = event.subject.x;\n  event.subject.fy = event.subject.y;\n}\n\nfunction dragged(event) {\n  event.subject.fx = event.x;\n  event.subject.fy = event.y;\n}\n\nfunction dragended(event) {\n  if (!event.active) simulation.alphaTarget(0);\n  event.subject.fx = null;\n  event.subject.fy = null;\n}\n```\n\n## Adding interactivity\n\n### Tooltips\n\n```javascript\n// Create tooltip div (outside SVG)\nconst tooltip = d3.select(\"body\").append(\"div\")\n  .attr(\"class\", \"tooltip\")\n  .style(\"position\", \"absolute\")\n  .style(\"visibility\", \"hidden\")\n  .style(\"background-color\", \"white\")\n  .style(\"border\", \"1px solid #ddd\")\n  .style(\"padding\", \"10px\")\n  .style(\"border-radius\", \"4px\")\n  .style(\"pointer-events\", \"none\");\n\n// Add to elements\ncircles\n  .on(\"mouseover\", function(event, d) {\n    d3.select(this).attr(\"opacity\", 1);\n    tooltip\n      .style(\"visibility\", \"visible\")\n      .html(`<strong>${d.label}</strong><br/>Value: ${d.value}`);\n  })\n  .on(\"mousemove\", function(event) {\n    tooltip\n      .style(\"top\", (event.pageY - 10) + \"px\")\n      .style(\"left\", (event.pageX + 10) + \"px\");\n  })\n  .on(\"mouseout\", function() {\n    d3.select(this).attr(\"opacity\", 0.7);\n    tooltip.style(\"visibility\", \"hidden\");\n  });\n```\n\n### Zoom and pan\n\n```javascript\nconst zoom = d3.zoom()\n  .scaleExtent([0.5, 10])\n  .on(\"zoom\", (event) => {\n    g.attr(\"transform\", event.transform);\n  });\n\nsvg.call(zoom);\n```\n\n### Click interactions\n\n```javascript\ncircles\n  .on(\"click\", function(event, d) {\n    // Handle click (dispatch event, update app state, etc.)\n    console.log(\"Clicked:\", d);\n\n    // Visual feedback\n    d3.selectAll(\"circle\").attr(\"fill\", \"steelblue\");\n    d3.select(this).attr(\"fill\", \"orange\");\n\n    // Optional: dispatch custom event for your framework/app to listen to\n    // window.dispatchEvent(new CustomEvent(''chartClick'', { detail: d }));\n  });\n```\n\n## Transitions and animations\n\nAdd smooth transitions to visual changes:\n\n```javascript\n// Basic transition\ncircles\n  .transition()\n  .duration(750)\n  .attr(\"r\", 10);\n\n// Chained transitions\ncircles\n  .transition()\n  .duration(500)\n  .attr(\"fill\", \"orange\")\n  .transition()\n  .duration(500)\n  .attr(\"r\", 15);\n\n// Staggered transitions\ncircles\n  .transition()\n  .delay((d, i) => i * 50)\n  .duration(500)\n  .attr(\"cy\", d => yScale(d.value));\n\n// Custom easing\ncircles\n  .transition()\n  .duration(1000)\n  .ease(d3.easeBounceOut)\n  .attr(\"r\", 10);\n```\n\n## Scales reference\n\n### Quantitative scales\n\n```javascript\n// Linear scale\nconst xScale = d3.scaleLinear()\n  .domain([0, 100])\n  .range([0, 500]);\n\n// Log scale (for exponential data)\nconst logScale = d3.scaleLog()\n  .domain([1, 1000])\n  .range([0, 500]);\n\n// Power scale\nconst powScale = d3.scalePow()\n  .exponent(2)\n  .domain([0, 100])\n  .range([0, 500]);\n\n// Time scale\nconst timeScale = d3.scaleTime()\n  .domain([new Date(2020, 0, 1), new Date(2024, 0, 1)])\n  .range([0, 500]);\n```\n\n### Ordinal scales\n\n```javascript\n// Band scale (for bar charts)\nconst bandScale = d3.scaleBand()\n  .domain([''A'', ''B'', ''C'', ''D''])\n  .range([0, 400])\n  .padding(0.1);\n\n// Point scale (for line/scatter categories)\nconst pointScale = d3.scalePoint()\n  .domain([''A'', ''B'', ''C'', ''D''])\n  .range([0, 400]);\n\n// Ordinal scale (for colours)\nconst colourScale = d3.scaleOrdinal(d3.schemeCategory10);\n```\n\n### Sequential scales\n\n```javascript\n// Sequential colour scale\nconst colourScale = d3.scaleSequential(d3.interpolateBlues)\n  .domain([0, 100]);\n\n// Diverging colour scale\nconst divScale = d3.scaleDiverging(d3.interpolateRdBu)\n  .domain([-10, 0, 10]);\n```\n\n## Best practices\n\n### Data preparation\n\nAlways validate and prepare data before visualisation:\n\n```javascript\n// Filter invalid values\nconst cleanData = data.filter(d => d.value != null && !isNaN(d.value));\n\n// Sort data if order matters\nconst sortedData = [...data].sort((a, b) => b.value - a.value);\n\n// Parse dates\nconst parsedData = data.map(d => ({\n  ...d,\n  date: d3.timeParse(\"%Y-%m-%d\")(d.date)\n}));\n```\n\n### Performance optimisation\n\nFor large datasets (>1000 elements):\n\n```javascript\n// Use canvas instead of SVG for many elements\n// Use quadtree for collision detection\n// Simplify paths with d3.line().curve(d3.curveStep)\n// Implement virtual scrolling for large lists\n// Use requestAnimationFrame for custom animations\n```\n\n### Accessibility\n\nMake visualisations accessible:\n\n```javascript\n// Add ARIA labels\nsvg.attr(\"role\", \"img\")\n   .attr(\"aria-label\", \"Bar chart showing quarterly revenue\");\n\n// Add title and description\nsvg.append(\"title\").text(\"Quarterly Revenue 2024\");\nsvg.append(\"desc\").text(\"Bar chart showing revenue growth across four quarters\");\n\n// Ensure sufficient colour contrast\n// Provide keyboard navigation for interactive elements\n// Include data table alternative\n```\n\n### Styling\n\nUse consistent, professional styling:\n\n```javascript\n// Define colour palettes upfront\nconst colours = {\n  primary: ''#4A90E2'',\n  secondary: ''#7B68EE'',\n  background: ''#F5F7FA'',\n  text: ''#333333'',\n  gridLines: ''#E0E0E0''\n};\n\n// Apply consistent typography\nsvg.selectAll(\"text\")\n  .style(\"font-family\", \"Inter, sans-serif\")\n  .style(\"font-size\", \"12px\");\n\n// Use subtle grid lines\ng.selectAll(\".tick line\")\n  .attr(\"stroke\", colours.gridLines)\n  .attr(\"stroke-dasharray\", \"2,2\");\n```\n\n## Common issues and solutions\n\n**Issue**: Axes not appearing\n- Ensure scales have valid domains (check for NaN values)\n- Verify axis is appended to correct group\n- Check transform translations are correct\n\n**Issue**: Transitions not working\n- Call `.transition()` before attribute changes\n- Ensure elements have unique keys for proper data binding\n- Check that useEffect dependencies include all changing data\n\n**Issue**: Responsive sizing not working\n- Use ResizeObserver or window resize listener\n- Update dimensions in state to trigger re-render\n- Ensure SVG has width/height attributes or viewBox\n\n**Issue**: Performance problems\n- Limit number of DOM elements (consider canvas for >1000 items)\n- Debounce resize handlers\n- Use `.join()` instead of separate enter/update/exit selections\n- Avoid unnecessary re-renders by checking dependencies\n\n## Resources\n\n### references/\nContains detailed reference materials:\n- `d3-patterns.md` - Comprehensive collection of visualisation patterns and code examples\n- `scale-reference.md` - Complete guide to d3 scales with examples\n- `colour-schemes.md` - D3 colour schemes and palette recommendations\n\n### assets/\n\nContains boilerplate templates:\n\n- `chart-template.js` - Starter template for basic chart\n- `interactive-template.js` - Template with tooltips, zoom, and interactions\n- `sample-data.json` - Example datasets for testing\n\nThese templates work with vanilla JavaScript, React, Vue, Svelte, or any other JavaScript environment. Adapt them as needed for your specific framework.\n\nTo use these resources, read the relevant files when detailed guidance is needed for specific visualisation types or patterns.\n"},"lastSynced":"2026-03-04T14:24:05.855Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced interactive data visualization capabilities with d3.js","zh":"非常适合需要高级交互式数据可视化功能的前端代理，使用d3.js","ja":"d3.jsを使用して高度なインタラクティブなデータ視覚化機能を必要とするフロントエンドエージェントに最適","ko":"d3.js를 사용하여 고급 인터랙티브 데이터 시각화 기능이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan capacidades de visualización de datos interactivos avanzados con d3.js","fr":"Parfait pour les agents Frontend qui ont besoin de capacités de visualisation de données interactives avancées avec d3.js","de":"Perfekt für Frontend-Agents, die erweiterte interaktive Datenvisualisierungsfunktionen mit d3.js benötigen","pt":"Perfeito para Agentes Frontend que precisam de capacidades avançadas de visualização de dados interativos com d3.js","ru":"Идеально для фронтенд-агентов, которым требуются продвинутые возможности интерактивной визуализации данных с помощью d3.js","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى قدرات متقدمة في ترسيم البيانات التفاعلية مع d3.js"},"recommendation":{"en":"Empowers agents to create sophisticated, interactive data visualisations by binding data to DOM elements and applying data-driven transformations using d3.js, with support for various JavaScript environments including vanilla JavaScript, React, Vue, and Svelte","zh":"赋予代理创建复杂的交互式数据可视化能力，通过将数据绑定到DOM元素，并使用d3.js应用数据驱动的变换，支持包括vanilla JavaScript、React、Vue和Svelte在内的各种JavaScript环境","ja":"d3.jsを使用してデータをDOM要素にバインドし、データ駆動の変換を適用することで、エージェントが複雑なインタラクティブなデータ視覚化を作成できるようにし、vanilla JavaScript、React、Vue、Svelteを含む様々なJavaScript環境をサポート","ko":"d3.js를 사용하여 데이터를 DOM 요소에 바인딩하고 데이터 주도 변환을 적용하여 에이전트가 복잡한 인터랙티브 데이터 시각화를 생성할 수 있도록 하며, vanilla JavaScript, React, Vue, Svelte를 포함한 다양한 JavaScript 환경을 지원","es":"Habilita a los agentes a crear visualizaciones de datos sofisticadas e interactivas vinculando datos a elementos DOM y aplicando transformaciones impulsadas por datos con d3.js, con soporte para varios entornos de JavaScript, incluyendo JavaScript vanilla, React, Vue y Svelte","fr":"Permet aux agents de créer des visualisations de données sophistiquées et interactives en liant des données à des éléments DOM et en appliquant des transformations pilotées par des données avec d3.js, avec un support pour différents environnements JavaScript, notamment JavaScript vanilla, React, Vue et Svelte","de":"Ermöglicht es Agenten, komplexe, interaktive Datenvisualisierungen zu erstellen, indem sie Daten an DOM-Elemente binden und datengetriebene Transformationen mit d3.js anwenden, mit Unterstützung für verschiedene JavaScript-Umgebungen, einschließlich Vanilla-JavaScript, React, Vue und Svelte","pt":"Habilita os agentes a criar visualizações de dados sofisticadas e interativas, vinculando dados a elementos do DOM e aplicando transformações impulsionadas por dados usando d3.js, com suporte a vários ambientes JavaScript, incluindo JavaScript vanilla, React, Vue e Svelte","ru":"Наделяет агентов возможностью создавать сложные интерактивные визуализации данных, привязывая данные к элементам DOM и применяя данные, управляемые трансформациями, с помощью d3.js, с поддержкой различных сред JavaScript, включая ванильный JavaScript, React, Vue и Svelte","ar":"يمنح الوكلاء القدرة على إنشاء ترسيمات بيانات متقدمة ومتفاعلة من خلال ربط البيانات بعناصر DOM وتطبيق تحويلات مدفوعة بالبيانات باستخدام d3.js، مع دعم لمختلف بيئات JavaScript، بما في ذلك JavaScript الفانيليا، React، Vue و Svelte"},"useCases":{"en":["Visualizing codebase structures with interactive SVG elements","Generating custom, publication-quality visualisations with precise control over every visual element","Creating dynamic data-driven documents with d3.js across multiple JavaScript frameworks"],"zh":["使用交互式SVG元素可视化代码库结构","生成自定义的出版级视觉效果，并对每个视觉元素具有精确的控制权，使用d3.js","使用d3.js跨多个JavaScript框架创建动态数据驱动文档"],"ja":["インタラクティブなSVG要素を使用してコードベースの構造を視覚化する","カスタムの出版質の視覚化を生成し、d3.jsを使用して各視覚要素を正確に制御する","d3.jsを使用して複数のJavaScriptフレームワークを跨いで動的なデータ駆動のドキュメントを作成する"],"ko":["인터랙티브 SVG 요소를 사용하여 코드베이스 구조 시각화","d3.js를 사용하여 사용자 지정 및 출판급 시각화 생성, 모든 시각 요소에 대한 정교한 제어","d3.js를 사용하여 다중 JavaScript 프레임워크에서 동적 데이터 주도 문서 생성"],"es":["Visualizar estructuras de código con elementos SVG interactivos","Generar visualizaciones personalizadas de alta calidad con control preciso sobre cada elemento visual","Crear documentos dinámicos impulsados por datos con d3.js en varios marcos de JavaScript"],"fr":["Visualiser les structures de codebase avec des éléments SVG interactifs","Générer des visualisations personnalisées de haute qualité avec un contrôle précis sur chaque élément visuel","Créer des documents dynamiques pilotés par des données avec d3.js sur plusieurs cadres JavaScript"],"de":["Visualisierung von Codebasen-Strukturen mit interaktiven SVG-Elementen","Erzeugen von benutzerdefinierten, publizierfähigen Visualisierungen mit präziser Kontrolle über jedes visuelle Element","Erstellen von dynamischen, datengetriebenen Dokumenten mit d3.js über mehrere JavaScript-Frameworks"],"pt":["Visualizar estruturas de código com elementos SVG interativos","Gerar visualizações personalizadas de publicação de alta qualidade com controle preciso sobre cada elemento visual","Criar documentos dinâmicos impulsionados por dados com d3.js em vários frameworks JavaScript"],"ru":["Визуализация структур кода с помощью интерактивных элементов SVG","Генерация индивидуальных визуализаций высокого качества с точным контролем над каждым визуальным элементом","Создание динамических документов, управляемых данными, с помощью d3.js в нескольких фреймворках JavaScript"],"ar":["ترسيم هيكل الكود باستخدام عناصر SVG التفاعلية","إنشاء ترسيمات مخصصة منشورات عالية الجودة مع التحكم الدقيق في كل عنصر مرئي","إنشاء مستندات ديناميكية مدفوعة بالبيانات مع d3.js عبر عدة إطارات عمل JavaScript"]},"limitations":{"en":["Requires knowledge of JavaScript and d3.js","Limited to web-based applications","May require additional setup for compatibility with certain JavaScript frameworks"],"zh":["需要JavaScript和d3.js的知识","仅限于基于Web的应用程序","可能需要额外的设置以便与某些JavaScript框架兼容"],"ja":["JavaScriptとd3.jsの知識が必要","Webベースのアプリケーションに限定される","一部のJavaScriptフレームワークとの互換性を確保するために追加の設定が必要になる可能性がある"],"ko":["JavaScript 및 d3.js 지식 필요","웹 기반 응용 프로그램으로 제한","일부 JavaScript 프레임워크와의 호환성을 보장하기 위해 추가 설정이 필요할 수 있음"],"es":["Requiere conocimiento de JavaScript y d3.js","Limitado a aplicaciones basadas en web","Puede requerir una configuración adicional para la compatibilidad con ciertos marcos de JavaScript"],"fr":["Nécessite des connaissances en JavaScript et d3.js","Limité aux applications basées sur le web","Peut nécessiter une configuration supplémentaire pour la compatibilité avec certains cadres JavaScript"],"de":["Benötigt Kenntnisse in JavaScript und d3.js","Begrenzt auf webbasierte Anwendungen","Kann eine zusätzliche Einrichtung für die Kompatibilität mit bestimmten JavaScript-Frameworks erfordern"],"pt":["Exige conhecimento de JavaScript e d3.js","Limitado a aplicações baseadas na web","Pode requerer configuração adicional para compatibilidade com certos frameworks JavaScript"],"ru":["Требует знания JavaScript и d3.js","Ограничен веб-приложениями","Может потребовать дополнительной настройки для совместимости с определенными фреймворками JavaScript"],"ar":["يتطلب معرفة JavaScript و d3.js","محدود للتطبيقات المستندة إلى الويب","قد يتطلب إعدادًا إضافيًا للتوافق مع بعض إطارات العمل JavaScript"]},"version":3},"contentHash":"4b1f820cd87c55dc6b7c714a76c1320903187967cd43f3b4db9d6eacbcc085b3","qualityScore":49}');
