INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tigrisdata/tigris-blog/xe-writing-style', 'xe-writing-style', 'tigrisdata', 'tigris-blog', 'community', 'xe-writing-style tigrisdata tigris-blog community xe-writing-style 是一个专注于存储的博客，涵盖存储解决方案和 AI 智能工具的相关内容 xe-writing-style はストレージに特化したブログで、ストレージソリューションと AI エージェントに関する内容を扱う xe-writing-style 은 저장소에 중점을 둔 블로그로 저장소 솔루션과 AI 에이전트 관련 콘텐츠를 다룸 xe-writing-style es un blog dedicado a todo lo relacionado con el almacenamiento, explorando las últimas tendencias y tecnologías xe-writing-style est un blog consacré à tout ce qui concerne le stockage, explorant les dernières tendances et technologies xe-writing-style ist ein Blog, der sich allem widmet, was mit der Speicherung zu tun hat, und die neuesten Trends und Technologien erkundet A xe-writing-style é uma ferramenta de IA dedicada a tudo relacionado ao armazenamento, ajudando desenvolvedores a melhorar suas habilidades ИИ Агент xe-writing-style - это блог, посвященный всем аспектам хранилищ, помогающий разработчикам улучшить свои навыки أداة xe-writing-style هي أداة ذكاء اصطناعي مخصصة لجميع الأمور المتعلقة بالتخزين، تساعد المطورين على تحسين مهاراتهم A blog dedicated to all things storage! 如何使用 xe-writing-style 什么是存储解决方案 xe-writing-style 替代品 xe-writing-style 与竞争对手 xe-writing-style 安装 xe-writing-style 设置指南 AI 智能工具 存储博客 存储知识 A blog dedicated to all things storage!');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('madihg/oulipo/oulipo-brand', 'community', 'madihg', 'oulipo', 'madihg/oulipo', 'oulipo-brand', 0, 0, 49, '2026-03-04T13:07:01.803Z', '2026-03-04T14:30:24.604Z', '470a8298d07e143228dd2c2142f5a326017a30d320f95ba0408bffcd10be4b1c', '{"id":"madihg/oulipo/oulipo-brand","name":"oulipo-brand","description":{"zh":"oulipo-brand 是一个实验性的计算机诗歌平台，利用AI智能创作创新诗歌","ja":"oulipo-brandは、実験的コンピュータ詩のためのホームです","ko":"oulipo-brand는 실험적 컴퓨터 시를 위한 플랫폼입니다","es":"Oulipo Brand es el hogar de la poesía computacional experimental, donde la creatividad y la tecnología se unen","fr":"Oulipo Brand est le berceau de la poésie computationnelle expérimentale, où la créativité et la technologie se rencontrent","de":"Oulipo Brand ist die Heimat der experimentellen computergenerierten Poesie, wo Kreativität und Technologie sich vereinen","pt":"Oulipo-Brand é uma plataforma experimental de poesia computacional para desenvolvedores, permitindo a criação de poemas inovadores.","ru":"Oulipo-Brand - это экспериментальная платформа компьютерной поэзии для разработчиков, позволяющая создавать инновационные произведения.","ar":"Oulipo-Brand هي منصة شعر حاسوبي تجريبية للمطورين، تمكن من إنشاء القصائد المبتكرة.","en":"Home of experimental computational poetry"},"seo":{"title":{"zh":"oulipo-brand AI智能诗歌实验","ja":"oulipo-brand AIエージェントによる実験的コンピュータ詩","ko":"oulipo-brand AI 에이전트 실험적 컴퓨터 시","es":"Herramientas de poesía computacional experimental - Oulip...","fr":"Outils de poésie computationnelle expérimentale - Oulipo ...","de":"Experimentelle computergenerierte Poesie-Tools - Oulipo B...","pt":"Ferramentas de Poesia Computacional Oulipo-Brand","ru":"ИИ Агенты: Экспериментальная Поэзия Oulipo-Brand","ar":"أدوات الشعر الحاسوبي التجريبية Oulipo-Brand","en":"oulipo-brand"},"description":{"zh":"oulipo-brand 是一个实验性的计算机诗歌平台，利用AI智能创作创新诗歌","ja":"oulipo-brandは、実験的コンピュータ詩のためのホームです","ko":"oulipo-brand는 실험적 컴퓨터 시를 위한 플랫폼입니다","es":"Oulipo Brand es el hogar de la poesía computacional experimental, donde la creatividad y la tecnología se unen","fr":"Oulipo Brand est le berceau de la poésie computationnelle expérimentale, où la créativité et la technologie se rencontrent","de":"Oulipo Brand ist die Heimat der experimentellen computergenerierten Poesie, wo Kreativität und Technologie sich vereinen","pt":"Oulipo-Brand é uma plataforma experimental de poesia computacional para desenvolvedores, permitindo a criação de poemas inovadores.","ru":"Oulipo-Brand - это экспериментальная платформа компьютерной поэзии для разработчиков, позволяющая создавать инновационные произведения.","ar":"Oulipo-Brand هي منصة شعر حاسوبي تجريبية للمطورين، تمكن من إنشاء القصائد المبتكرة.","en":"Home of experimental computational poetry"},"definition":{"en":"Home of experimental computational poetry"},"features":{"zh":["AI智能诗歌创作","实验性的计算机诗歌","创新诗歌形式","Python和Node.js集成","CLI工具支持"],"ja":["AIエージェントによる詩歌創作","実験的コンピュータ詩","革新的詩歌形式","PythonとNode.jsの統合","CLIツールのサポート"],"ko":["AI 에이전트를 사용한 시 창작","실험적 컴퓨터 시","혁신적인 시 형식","Python과 Node.js 통합","CLI 툴 지원"],"es":["Generación de poesía automática con Python","Integración con Node.js para aplicaciones web","Uso de CLI para ejecutar comandos de poesía","Compatibilidad con React para interfaces de usuario personalizadas","Acceso a una comunidad de desarrolladores de poesía computacional"],"fr":["Génération de poésie automatique avec Python","Intégration avec Node.js pour des applications web","Utilisation de CLI pour exécuter des commandes de poésie","Compatibilité avec React pour des interfaces utilisateur personnalisées","Accès à une communauté de développeurs de poésie computationnelle"],"de":["Automatische Gedichtgenerierung mit Python","Integration mit Node.js für Webanwendungen","Verwendung von CLI für die Ausführung von Gedicht-Befehlen","Kompatibilität mit React für benutzerdefinierte Benutzeroberflächen","Zugang zu einer Community von Entwicklern für computergenerierte Poesie"],"pt":["Criação de poemas inovadores","Experimentação com linguagem natural","Integração com tecnologias de IA","Desenvolvimento de algoritmos poéticos","Comunidade de desenvolvedores de poesia computacional"],"ru":["Создание инновационных произведений","Эксперименты с естественным языком","Интеграция с технологиями ИИ","Разработка поэтических алгоритмов","Сообщество разработчиков компьютерной поэзии"],"ar":["إنشاء القصائد المبتكرة","التجارب مع اللغة الطبيعية","التكامل مع تقنيات الذكاء الاصطناعي","تطوير الخوارزميات الشعرية","مجتمع المطورين للشعر الحاسوبي"]},"keywords":{"zh":["如何使用oulipo-brand","什么是计算机诗歌","oulipo-brand替代品","oulipo-brand vs 其他AI工具","oulipo-brand安装","oulipo-brand设置指南","AI智能诗歌创作","实验性计算机诗歌"],"ja":["oulipo-brandの使い方","コンピュータ詩とは","oulipo-brandの代替","oulipo-brand vs 他のAIツール","oulipo-brandのインストール","oulipo-brandの設定ガイド","AIエージェントによる詩歌創作","実験的コンピュータ詩"],"ko":["oulipo-brand 사용법","컴퓨터 시란 무엇인가","oulipo-brand 대안","oulipo-brand vs 다른 AI 툴","oulipo-brand 설치","oulipo-brand 설정 가이드","AI 에이전트를 사용한 시 창작","실험적 컴퓨터 시"],"es":["herramientas de poesía computacional","poesía generativa con Python","alternativas a Oulipo Brand","Oulipo Brand vs otros herramientas de poesía","cómo instalar Oulipo Brand","guía de configuración de Oulipo Brand","poesía computacional experimental","desarrollo de aplicaciones de poesía"],"fr":["outils de poésie computationnelle","poésie générative avec Python","alternatives à Oulipo Brand","Oulipo Brand vs autres outils de poésie","comment installer Oulipo Brand","guide de configuration de Oulipo Brand","poésie computationnelle expérimentale","développement d''applications de poésie"],"de":["computergenerierte Poesie-Tools","Gedichtgenerierung mit Python","Alternativen zu Oulipo Brand","Oulipo Brand vs andere Poesie-Tools","wie man Oulipo Brand installiert","Konfigurationsanleitung für Oulipo Brand","experimentelle computergenerierte Poesie","Entwicklung von Poesie-Anwendungen"],"pt":["como usar Oulipo-Brand","o que é poesia computacional","Oulipo-Brand alternativa","Oulipo-Brand vs outras plataformas","instalar Oulipo-Brand","guia de configuração Oulipo-Brand","desenvolvimento de poesia computacional","linguagem natural e IA"],"ru":["как использовать Oulipo-Brand","что такое компьютерная поэзия","ИИ Агенты для поэзии","Oulipo-Brand альтернатива","Oulipo-Brand vs другие платформы","установить Oulipo-Brand","руководство по настройке Oulipo-Brand","разработка компьютерной поэзии","естественный язык и ИИ"],"ar":["كيفية استخدام Oulipo-Brand","ما هي الشعر الحاسوبي","أدوات الذكاء الاصطناعي للشعر","Oulipo-Brand بديل","Oulipo-Brand مقابل منصات أخرى","تثبيت Oulipo-Brand","دليل إعداد Oulipo-Brand","تطوير الشعر الحاسوبي","اللغة الطبيعية والذكاء الاصطناعي"]}},"owner":"madihg","repo":"oulipo","repoPath":"madihg/oulipo","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.803Z","topics":[],"category":"community","skillMd":{"name":"oulipo-brand","description":"Oulipo.xyz brand guidelines and design system. Typography: Standard (body), Terminal Grotesque (h1), Diatype Variable (headings, captions, metadata). Colors: white background, dark text. Use when building or modifying oulipo.xyz pages, components, or related projects.","bodyPreview":"# Oulipo.xyz Brand Guidelines\n\nDesign system and brand guidelines for oulipo.xyz — a laboratory of experimental computational poetry by Halim Madi.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Building new pages for oulipo.xyz\n- Modifying existing oulipo components\n- Creating related projects that should match the oulipo aesthetic\n- Reviewing design consistency across the site\n\n---\n\n## Typography\n\n### Font Stack\n\n| Font                      | Usage","body":"# Oulipo.xyz Brand Guidelines\n\nDesign system and brand guidelines for oulipo.xyz — a laboratory of experimental computational poetry by Halim Madi.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Building new pages for oulipo.xyz\n- Modifying existing oulipo components\n- Creating related projects that should match the oulipo aesthetic\n- Reviewing design consistency across the site\n\n---\n\n## Typography\n\n### Font Stack\n\n| Font                      | Usage                                             | Weight                 | Source    |\n| ------------------------- | ------------------------------------------------- | ---------------------- | --------- |\n| **Standard**              | Body text, navigation, hero subtitle              | Book (400), Bold (700) | Cargo CDN |\n| **Terminal Grotesque**    | Main h1 headings only                             | Regular (400)          | Cargo CDN |\n| **Diatype Variable**      | h2 headings                                       | 200-1000 (variable)    | Cargo CDN |\n| **Diatype Mono Variable** | Captions, work titles, metadata (with `''MONO'' 1`) | 200-1000 (variable)    | Cargo CDN |\n\n### Font Face Declarations\n\n```css\n/* Standard - Body Font */\n@font-face {\n  font-display: block;\n  font-family: \"Standard\";\n  src: url(\"https://type.cargo.site/files/Standard-Book.woff\") format(\"woff\");\n  font-style: normal;\n  font-weight: normal;\n}\n@font-face {\n  font-display: block;\n  font-family: \"Standard\";\n  src: url(\"https://type.cargo.site/files/Standard-Bold.woff\") format(\"woff\");\n  font-style: normal;\n  font-weight: bold;\n}\n\n/* Terminal Grotesque - Display Font for h1 */\n@font-face {\n  font-display: block;\n  font-family: \"Terminal Grotesque\";\n  src: url(\"https://type.cargo.site/files/TerminalGrotesque.woff\")\n    format(\"woff\");\n  font-style: normal;\n  font-weight: normal;\n}\n\n/* Diatype Variable - h2 Headings (proportional) */\n@font-face {\n  font-display: block;\n  font-family: \"Diatype Variable\";\n  src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n    format(\"woff2-variations\");\n  font-style: normal;\n  font-weight: 200 1000;\n}\n\n/* Diatype Mono Variable - Captions, Work Titles, Metadata (monospace) */\n@font-face {\n  font-display: block;\n  font-family: \"Diatype Mono Variable\";\n  src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n    format(\"woff2-variations\");\n  font-style: normal;\n  font-weight: 200 1000;\n}\n```\n\n### Font Variation Settings\n\nThe Diatype Plus Variable font supports axis switching between proportional and monospace:\n\n```css\n/* Proportional (Diatype Variable) */\nfont-variation-settings:\n  \"slnt\" 0,\n  \"MONO\" 0;\n\n/* Monospace (Diatype Mono Variable) - USE THIS FOR CAPTIONS */\nfont-variation-settings:\n  \"slnt\" 0,\n  \"MONO\" 1;\n```\n\n### Typography Specifications\n\n| Element          | Font Family        | Size                            | Weight | Line Height |\n| ---------------- | ------------------ | ------------------------------- | ------ | ----------- |\n| `body`           | Standard           | 1.3rem                          | 400    | 1.2         |\n| `h1`             | Terminal Grotesque | 7rem (desktop), 4.5rem (mobile) | 400    | 0.9         |\n| `h2`             | Diatype Variable   | 2rem                            | 700    | 1.2         |\n| `.caption`       | Diatype Variable   | 1.2rem                          | 400    | 1.25        |\n| `.work-title`    | Diatype Variable   | 1.1rem                          | 400    | —           |\n| `.work-meta`     | Diatype Variable   | 0.9rem                          | 400    | —           |\n| `.hero-subtitle` | Standard           | 1rem                            | 400    | 1.4         |\n\n---\n\n## Colors\n\n### Core Palette\n\n| Name                | Value                 | Usage              |\n| ------------------- | --------------------- | ------------------ |\n| **Background**      | `#ffffff`             | Page background    |\n| **Primary Text**    | `rgba(0, 0, 0, 0.85)` | Body text, links   |\n| **Black**           | `#000000`             | Headings, captions |\n| **Muted Text**      | `rgba(0, 0, 0, 0.7)`  | Descriptions       |\n| **Subtle Text**     | `rgba(0, 0, 0, 0.5)`  | Metadata, dates    |\n| **Subtle Text Alt** | `rgba(0, 0, 0, 0.6)`  | Section subtitles  |\n| **Border/Divider**  | `rgba(0, 0, 0, 0.75)` | Horizontal rules   |\n| **Overlay**         | `rgba(0, 0, 0, 0.25)` | Menu overlay       |\n\n### CSS Variables (Optional)\n\n```css\n:root {\n  --oulipo-bg: #ffffff;\n  --oulipo-text: rgba(0, 0, 0, 0.85);\n  --oulipo-text-black: #000000;\n  --oulipo-text-muted: rgba(0, 0, 0, 0.7);\n  --oulipo-text-subtle: rgba(0, 0, 0, 0.5);\n  --oulipo-border: rgba(0, 0, 0, 0.75);\n  --oulipo-overlay: rgba(0, 0, 0, 0.25);\n}\n```\n\n---\n\n## Layout\n\n### Spacing\n\n| Element           | Value                         |\n| ----------------- | ----------------------------- |\n| Page padding      | 4rem (desktop), 2rem (mobile) |\n| Max content width | 1200px                        |\n| Section margin    | 3rem bottom                   |\n| Grid gap          | 2rem                          |\n\n### Grid System\n\n```css\n/* 3-column grid on desktop */\n.grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 2rem;\n}\n\n/* 2-column on tablet (≤900px) */\n@media (max-width: 900px) {\n  .grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n/* 1-column on mobile (≤600px) */\n@media (max-width: 600px) {\n  .grid {\n    grid-template-columns: 1fr;\n  }\n}\n```\n\n### Featured Work Layout\n\n```css\n/* Image 2/3, Description 1/3 */\n.work-featured-body {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 2rem;\n}\n\n@media (max-width: 900px) {\n  .work-featured-body {\n    grid-template-columns: 1fr;\n  }\n}\n```\n\n---\n\n## Components\n\n### Links\n\n```css\na {\n  color: rgba(0, 0, 0, 0.85);\n  text-decoration: underline;\n}\n\na:hover {\n  opacity: 0.7;\n}\n```\n\n### Horizontal Rule\n\n```css\nhr {\n  background: rgba(0, 0, 0, 0.75);\n  border: 0;\n  height: 1px;\n  margin: 2rem 0;\n}\n```\n\n### Side Menu\n\n- Width: 420px (desktop), 100% (mobile)\n- Background: white\n- Slide in from right\n- Line height for links: 1.15\n\n---\n\n## Site Structure\n\n### Current Sections\n\n1. **Featured Works** (max 3 items) — Highlighted projects with image + description\n2. **Selected Works** — Additional notable works\n3. **Non Human Poets** — AI/machine poetry experiments\n4. **Border/line** — Immigration-themed interactive series\n5. **Somatic Poetry Sandbox** — Experimental interactive pieces\n\n### Navigation\n\n- Top-left: \"Halim Madi\" link (hides on scroll)\n- Top-right: Hamburger menu (hides on scroll)\n- Side drawer with links to halimmadi.com sections\n\n---\n\n## File Organization\n\n```\noulipo/\n├── index.html              # Main landing page\n├── Assets/\n│   ├── screenshots/        # Work screenshots\n│   └── curl-screenshot.png\n├── borderline/             # Border/line series\n├── somatic-poetry-sandbox/ # Interactive experiments\n├── curl/                   # Curl project\n├── becoming-borders/       # Becoming Borders project\n├── case-against-the-son/   # Case Against the Son\n└── unlisted/               # Unlisted/archived works\n```\n\n---\n\n## Quick Copy-Paste\n\n### Minimal HTML Head\n\n```html\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Page Title — oulipo.xyz</title>\n  <style>\n    @font-face {\n      font-family: \"Standard\";\n      src: url(\"https://type.cargo.site/files/Standard-Book.woff\")\n        format(\"woff\");\n    }\n    @font-face {\n      font-family: \"Terminal Grotesque\";\n      src: url(\"https://type.cargo.site/files/TerminalGrotesque.woff\")\n        format(\"woff\");\n    }\n    @font-face {\n      font-family: \"Diatype Variable\";\n      src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n        format(\"woff2-variations\");\n      font-weight: 200 1000;\n    }\n    body {\n      margin: 0;\n      padding: 4rem;\n      background: #ffffff;\n      color: rgba(0, 0, 0, 0.85);\n      font-family: Standard, sans-serif;\n      font-size: 1.3rem;\n      line-height: 1.2;\n    }\n    h1 {\n      font-family: \"Terminal Grotesque\", sans-serif;\n      font-size: 7rem;\n      line-height: 0.9;\n    }\n    h2 {\n      font-family: \"Diatype Variable\", sans-serif;\n      font-size: 2rem;\n      font-weight: 700;\n    }\n  </style>\n</head>\n```\n\n---\n\n## Screenshots\n\n### IMPORTANT: Screenshot Border Requirements\n\n**All screenshots on oulipo.xyz MUST have a thin 1px black border.**\n\nWhen adding or updating screenshots:\n\n1. **Take the screenshot** of the work/page\n2. **Add a 1px black border** around the entire image\n3. **Save to** `Assets/screenshots/` with a descriptive name (e.g., `project-name.png`)\n\n### Adding Borders with Python (Pillow)\n\n```python\nfrom PIL import Image\n\ndef add_border(image_path, output_path=None, border_width=1, border_color=(0, 0, 0)):\n    \"\"\"Add a thin black border to a screenshot\"\"\"\n    if output_path is None:\n        output_path = image_path\n\n    img = Image.open(image_path)\n    new_width = img.width + 2 * border_width\n    new_height = img.height + 2 * border_width\n\n    bordered_img = Image.new(''RGB'', (new_width, new_height), border_color)\n    bordered_img.paste(img, (border_width, border_width))\n    bordered_img.save(output_path, quality=95)\n\n# Usage\nadd_border(\"Assets/screenshots/my-project.png\")\n```\n\n### Screenshot Naming Convention\n\n- Use lowercase with hyphens: `project-name.png`\n- Match the work title where possible\n- Store in `Assets/screenshots/`\n\n---\n\n## Brand Voice\n\nOulipo.xyz is described as:\n\n> \"A kitchen laboratory of experimental computational poetry. Non-human poets, anti-gravitational word interfaces, somatic semantics. This is where I break and mend things.\"\n\nKey themes:\n\n- Experimental and playful\n- Code meets poetry\n- Human-machine interaction\n- Border/migration/identity exploration\n- Somatic (body-based) interactions\n"},"lastSynced":"2026-03-04T14:30:24.604Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing experimental computational poetry generation and typography customization.","zh":"非常适合需要实验性计算机诗歌生成和排版自定义的创意代理。","ja":"実験的な計算機詩の生成やタイポグラフィのカスタマイズが必要なクリエイティブエージェントに最適。","ko":"실험적인 계산기 시 생성 및 타이포그래피 사용자 지정이 필요한 창의적 에이전트에 적합합니다.","es":"Perfecto para Agentes Creativos que necesitan generación de poesía computacional experimental y personalización de tipografía.","fr":"Parfait pour les Agents Créatifs ayant besoin de génération de poésie computationnelle expérimentale et de personnalisation de typographie.","de":"Perfekt für kreative Agenten, die experimentelle computergenerierte Poesie und Typografie-Anpassung benötigen.","pt":"Perfeito para Agentes Criativos que precisam de geração de poesia computacional experimental e personalização de tipografia.","ru":"Идеально подходит для Креативных Агентов, которым необходима экспериментальная вычислительная поэзия и настройка типографики.","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى توليد شعر حاسوبي تجريبي وتخصيص طباعة الحروف"},"recommendation":{"en":"Empowers agents to create visually stunning computational poetry using custom font stacks and design systems, leveraging typography guidelines for consistent branding across oulipo.xyz projects, including SVG and related file formats.","zh":"赋予代理创建视觉上令人惊叹的计算机诗歌的能力，使用自定义字体栈和设计系统，利用排版指南以实现oulipo.xyz项目（包括SVG和相关文件格式）的一致品牌形象。","ja":"カスタムフォントスタックとデザインシステムを使用して、視覚的に驚くべき計算機詩を作成するエージェントをEmpowerし、oulipo.xyzプロジェクト（SVGや関連ファイル形式を含む）全体で一貫したブランド化を実現するためのタイポグラフィガイドラインを活用する。","ko":"사용자 지정 글꼴 스택 및 디자인 시스템을 사용하여 시각적으로惊くべき 계산기 시를 만들 수 있는 에이전트를 Empower하고, oulipo.xyz 프로젝트(SVG 및 관련 파일 형식 포함) 전체에서 일관된 브랜드 이미지를 구현하기 위한 타이포그래피 가이드 라인을 활용합니다.","es":"Habilita a los agentes a crear poesía computacional visualmente impresionante utilizando pilas de fuentes personalizadas y sistemas de diseño, aprovechando las pautas de tipografía para una marca coherente en proyectos oulipo.xyz, incluyendo SVG y formatos de archivo relacionados.","fr":"Permet aux agents de créer une poésie computationnelle visuellement époustouflante en utilisant des piles de polices personnalisées et des systèmes de conception, en exploitant les directives de typographie pour une marque cohérente sur les projets oulipo.xyz, y compris les formats de fichier SVG et apparentés.","de":"Ermächtigt Agenten, visuell beeindruckende computergenerierte Poesie zu erstellen, indem sie benutzerdefinierte Schriftstapel und Designsysteme verwenden, um die Typografie-Richtlinien für eine konsistente Markenidentität in oulipo.xyz-Projekten, einschließlich SVG und verwandter Dateiformate, zu nutzen.","pt":"Habilita os agentes a criarem poesia computacional visualmente deslumbrante usando pilhas de fontes personalizadas e sistemas de design, aproveitando diretrizes de tipografia para consistência de marca em projetos oulipo.xyz, incluindo SVG e formatos de arquivo relacionados.","ru":"Наделяет агентов возможностью создавать визуально потрясающую вычислительную поэзию с помощью пользовательских стэков шрифтов и систем дизайна, используя руководства по типографике для последовательного брендинга в проектах oulipo.xyz, включая SVG и связанные форматы файлов.","ar":"تمكّن الوكلاء من إنشاء شعر حاسوبي مرئيًا مبهرًا باستخدام مجموعة من خطوط الحروف المخصصة وأنظمة التصميم، مستفيدًا من إرشادات الطباعة للحفاظ على التماسك العلامي عبر مشاريع oulipo.xyz، بما في ذلك SVG والتنسيقات المتصلة بها."},"useCases":{"en":["Generating experimental computational poetry","Customizing typography for brand consistency","Creating related projects with oulipo aesthetic"],"zh":["生成实验性计算机诗歌","自定义排版以实现品牌一致性","创建具有oulipo美学的相关项目"],"ja":["実験的な計算機詩の生成","ブランド一貫性のためのタイポグラフィのカスタマイズ","oulipoエステティックを使用した関連プロジェクトの作成"],"ko":["실험적인 계산기 시 생성","브랜드 일관성을 위한 타이포그래피 사용자 지정","oulipo 미학을 사용한 관련 프로젝트 생성"],"es":["Generación de poesía computacional experimental","Personalización de tipografía para la coherencia de la marca","Creación de proyectos relacionados con la estética oulipo"],"fr":["Génération de poésie computationnelle expérimentale","Personnalisation de la typographie pour la cohérence de la marque","Création de projets liés à l''esthétique oulipo"],"de":["Erzeugung experimenteller computergenerierter Poesie","Anpassung der Typografie für Markenkonsequenz","Erstellung von Projekten im Zusammenhang mit der oulipo-Ästhetik"],"pt":["Geração de poesia computacional experimental","Personalização de tipografia para consistência de marca","Criação de projetos relacionados com estética oulipo"],"ru":["Генерация экспериментальной вычислительной поэзии","Настройка типографики для последовательности бренда","Создание связанных проектов с эстетикой oulipo"],"ar":["توليد شعر حاسوبي تجريبي","تخصيص طباعة الحروف لاتساق العلامة","إنشاء مشاريع متصلة بتأثير oulipo"]},"limitations":{"en":["Requires design system knowledge","Specific to oulipo.xyz brand guidelines"],"zh":["需要设计系统知识","仅限oulipo.xyz品牌指南"],"ja":["デザインシステムの知識が必要","oulipo.xyzブランドガイドラインに特有"],"ko":["디자인 시스템 지식이 필요합니다.","oulipo.xyz 브랜드 가이드 라인에 특정"],"es":["Requiere conocimiento del sistema de diseño","Específico para las pautas de marca oulipo.xyz"],"fr":["Nécessite des connaissances en système de conception","Spécifique aux directives de marque oulipo.xyz"],"de":["Benötigt Kenntnisse des Designsystems","Spezifisch für die Markenrichtlinien von oulipo.xyz"],"pt":["Exige conhecimento de sistema de design","Específico para diretrizes de marca oulipo.xyz"],"ru":["Требует знания системы дизайна","Конкретно для руководств по бренду oulipo.xyz"],"ar":["يتطلب معرفة نظام التصميم","محدد لمرشدي العلامة التجارية oulipo.xyz"]},"version":3},"contentHash":"470a8298d07e143228dd2c2142f5a326017a30d320f95ba0408bffcd10be4b1c","qualityScore":49}');
