INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bivex/loreSystem/json-formatter', 'json-formatter', 'bivex', 'loreSystem', 'community', 'json-formatter bivex loreSystem community json-formatter是一种Worldbuilding软件，帮助开发者快速格式化JSON数据，减少手动编辑错误 JSONフォーマッターはWorldbuildingソフトウェアで、開発者がJSONデータを迅速に整形し、手動編集エラーを減らすのに役立ちます json-formatter는 Worldbuilding 소프트웨어로 개발자가 JSON 데이터를 빠르게 포맷팅하고 수동 편집 오류를減少하는 데 도움이 됩니다 El json-formatter es una herramienta de software de creación de mundos para desarrolladores que necesitan formatar datos JSON de manera eficiente Le json-formatter est un outil de logiciel de création de mondes pour les développeurs qui ont besoin de formater des données JSON de manière efficace Der json-formatter ist ein Software-Weltbildungstool für Entwickler, die Daten im JSON-Format effizient formatieren müssen A ferramenta json-formatter é uma solução para desenvolvedores que necessitam de formatação JSON eficaz em seus projetos de worldbuilding ИИ Агент json-formatter является решением для разработчиков, которым требуется эффективная форматировка JSON в их проектах по созданию миров أداة تنسيق JSON هي حل لبرمجة تطبيقات بناء العالم التي تحتاج إلى تنسيق JSON فعال Worldbuilding software json-formatter AI智能工具 JSON格式化 开发助手 Worldbuilding软件 如何使用json-formatter json-formatter替代品 json-formatter安装 Worldbuilding software');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pnils08/GodWorld/letters-desk', 'community', 'pnils08', 'GodWorld', 'pnils08/GodWorld', 'letters-desk', 0, 0, 49, '2026-03-04T13:07:01.902Z', '2026-03-04T14:57:44.379Z', 'e71e392e803cf26cc89ea4a5b5c25436ad585ed3b7d3a022071f70dc24b4cc95', '{"id":"pnils08/GodWorld/letters-desk","name":"letters-desk","description":{"zh":"letters-desk AI智能工具提供世界模拟功能，支持React、Python和Node.js开发","ja":"letters-desk AIエージェントはワールドシミュレーション機能を提供し、React、Python、Node.jsで開発可能","ko":"letters-desk AI 에이전트는 월드 시뮬레이션 기능을 제공하며 React, Python, Node.js로 개발할 수 있습니다","es":"letters-desk es una herramienta de AI que utiliza simulación mundial para mejorar la toma de decisiones","fr":"letters-desk est un outil d''IA qui utilise la simulation mondiale pour améliorer la prise de décision","de":"letters-desk ist ein KI-Tool, das die Welt-Simulation nutzt, um die Entscheidungsfindung zu verbessern","pt":"A letters-desk é uma ferramenta de simulação mundial que utiliza IA para criar ambientes realistas. Ela é ideal para desenvolvedores que buscam criar experiências imersivas.","ru":"Letters-desk - это инструмент мировой симуляции, использующий ИИ для создания реалистичных сред. Он идеален для разработчиков, которые хотят создавать иммерсивные trải nghiệm.","ar":"letters-desk هي أداة محاكاة عالمية تستخدم الذكاء الاصطناعي لإنشاء بيئات واقعية. وهي مثالية للمطورين الذين يبحثون عن إنشاء تجارب غامرة.","en":"World Simulation "},"seo":{"title":{"zh":"AI智能工具 letters-desk - 世界模拟","ja":"AIエージェント letters-desk - ワールドシミュレーション","ko":"AI 에이전트 letters-desk - 월드 시뮬레이션","es":"Herramientas de AI: letters-desk para Simulación Mundial","fr":"Outils d''IA : letters-desk pour Simulation Mondiale","de":"KI-Tools: letters-desk für Welt-Simulation","pt":"Ferramentas de IA: letters-desk Simulação Mundial","ru":"ИИ Агенты: letters-desk Мировая Симуляция","ar":"أدوات الذكاء الاصطناعي: letters-desk محاكاة العالم","en":"letters-desk"},"description":{"zh":"letters-desk AI智能工具提供世界模拟功能，支持React、Python和Node.js开发","ja":"letters-desk AIエージェントはワールドシミュレーション機能を提供し、React、Python、Node.jsで開発可能","ko":"letters-desk AI 에이전트는 월드 시뮬레이션 기능을 제공하며 React, Python, Node.js로 개발할 수 있습니다","es":"letters-desk es una herramienta de AI que utiliza simulación mundial para mejorar la toma de decisiones","fr":"letters-desk est un outil d''IA qui utilise la simulation mondiale pour améliorer la prise de décision","de":"letters-desk ist ein KI-Tool, das die Welt-Simulation nutzt, um die Entscheidungsfindung zu verbessern","pt":"A letters-desk é uma ferramenta de simulação mundial que utiliza IA para criar ambientes realistas. Ela é ideal para desenvolvedores que buscam criar experiê...","ru":"Letters-desk - это инструмент мировой симуляции, использующий ИИ для создания реалистичных сред. Он идеален для разработчиков, которые хотят создавать иммерс...","ar":"letters-desk هي أداة محاكاة عالمية تستخدم الذكاء الاصطناعي لإنشاء بيئات واقعية. وهي مثالية للمطورين الذين يبحثون عن إنشاء تجارب غامرة.","en":"World Simulation "},"definition":{"en":"World Simulation "},"features":{"zh":["世界模拟功能","支持React、Python和Node.js开发","CLI接口","Agent架构"],"ja":["ワールドシミュレーション機能","React、Python、Node.jsで開発可能","CLIインターフェース","エージェントアーキテクチャ"],"ko":["월드 시뮬레이션 기능","React, Python, Node.js로 개발할 수 있습니다","CLI 인터페이스","에이전트 아키텍처"],"es":["Simulación mundial en tiempo real","Análisis de datos avanzado","Integración con herramientas de desarrollo","Compatibilidad con múltiples plataformas","Soporte para lenguajes de programación como Python y Node.js"],"fr":["Simulation mondiale en temps réel","Analyse de données avancée","Intégration avec des outils de développement","Compatibilité avec plusieurs plates-formes","Support pour des langages de programmation tels que Python et Node.js"],"de":["Echtzeit-Welt-Simulation","Erweiterte Datenanalyse","Integration mit Entwicklungstools","Kompatibilität mit mehreren Plattformen","Unterstützung für Programmiersprachen wie Python und Node.js"],"pt":["Simulação mundial em tempo real","Ambientes realistas com IA","Ideal para desenvolvedores de jogos e experiências imersivas","Integração com React, Python e Node.js","CLI para controle e personalização"],"ru":["Мировая симуляция в реальном времени","Реалистичные среды с ИИ","Идеален для разработчиков игр и иммерсивных trải nghiệm","Интеграция с React, Python и Node.js","CLI для управления и настройки"],"ar":["محاكاة عالمية في الوقت الفعلي","بيئات واقعية مع الذكاء الاصطناعي","مثالية للمطورين الذين يبحثون عن إنشاء تجارب غامرة","التكامل مع React و Python و Node.js","CLI للتحكم والتحسين"]},"keywords":{"zh":["如何使用letters-desk","什么是世界模拟","letters-desk替代品","letters-desk vs 其他AI工具","letters-desk安装","letters-desk设置指南","AI智能工具","世界模拟技术"],"ja":["letters-deskの使用方法","ワールドシミュレーションとは","letters-deskの代替品","letters-desk vs その他のAIエージェント","letters-deskのインストール","letters-deskの設定ガイド","AIエージェント","ワールドシミュレーション技術"],"ko":["letters-desk 사용 방법","월드 시뮬레이션이란","letters-desk 대체품","letters-desk vs 다른 AI 에이전트","letters-desk 설치","letters-desk 설정 가이드","AI 에이전트","월드 시뮬레이션 기술"],"es":["herramientas de AI","simulación mundial","desarrollo de software","agentes de AI","cómo utilizar letters-desk","alternativas a letters-desk","instalación de letters-desk","guía de configuración de letters-desk"],"fr":["outils d''IA","simulation mondiale","développement de logiciels","agents d''IA","comment utiliser letters-desk","alternatives à letters-desk","installation de letters-desk","guide de configuration de letters-desk"],"de":["KI-Tools","Welt-Simulation","Software-Entwicklung","KI-Agents","wie man letters-desk verwendet","Alternativen zu letters-desk","Installation von letters-desk","Konfigurationsanleitung für letters-desk"],"pt":["como usar letters-desk","o que é simulação mundial","ferramentas de IA para desenvolvedores","alternativas para letters-desk","letters-desk vs outros instrumentos de simulação","instalar letters-desk","guias de configuração para letters-desk"],"ru":["как использовать letters-desk","что такое мировая симуляция","инструменты ИИ для разработчиков","альтернативы для letters-desk","letters-desk vs другие инструменты симуляции","установить letters-desk","руководства по настройке для letters-desk"],"ar":["كيفية استخدام letters-desk","ما هي محاكاة العالم","أدوات الذكاء الاصطناعي للمطورين","بديلات ل letters-desk","letters-desk مقابل أدوات محاكاة أخرى","تثبيت letters-desk","دليل الإعداد ل letters-desk"]}},"owner":"pnils08","repo":"GodWorld","repoPath":"pnils08/GodWorld","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.902Z","topics":[],"category":"community","skillMd":{"name":"letters-desk","description":"Letters to the Editor desk agent for The Cycle Pulse. Writes citizen voice letters responding to cycle events. Use when producing letters section of an edition.","bodyPreview":"## Editor''s Briefing\nYour editor''s briefing is pre-loaded in your prompt under **PRE-LOADED: EDITOR''S BRIEFING** (injected by the write-edition pipeline). It contains corrections from past editions, cross-desk coordination notes, character continuity pointers, and editorial guidance from Mags Corliss.\nLines prefixed with `ESTABLISHED CANON:` are non-negotiable facts (positions, vote outcomes, names). Treat them as immutable data — never contradict them in letter content.\nIf no pre-loaded briefin","body":"## Editor''s Briefing\nYour editor''s briefing is pre-loaded in your prompt under **PRE-LOADED: EDITOR''S BRIEFING** (injected by the write-edition pipeline). It contains corrections from past editions, cross-desk coordination notes, character continuity pointers, and editorial guidance from Mags Corliss.\nLines prefixed with `ESTABLISHED CANON:` are non-negotiable facts (positions, vote outcomes, names). Treat them as immutable data — never contradict them in letter content.\nIf no pre-loaded briefing appears in your prompt, check for one at: `output/desk-briefings/letters_briefing_c{XX}.md`\n\n## Pre-Write Guardian Check\nIf no guardian warnings were pre-loaded in your prompt, run this check before writing:\n1. Read `output/errata.jsonl` and scan for entries where `desk` is `letters` or `cross-desk`\n2. The letters desk has had **vote claim errors** — citizens making historical vote claims that weren''t verified. ALWAYS verify any vote reference in a letter against canonReference.recentOutcomes.\n\n# Letters to the Editor — Bay Tribune\n\nYou are writing citizen letters for The Cycle Pulse. These are NOT journalist pieces. These are Oakland residents writing to the paper in their own voice.\n\n## What Makes a Good Letter\n\nLetters are the heartbeat of the paper. They''re how the city talks back. A grandmother skeptical of the Stabilization Fund. A teenager hyped about a trade. A retired teacher reflecting on what her neighborhood used to be.\n\nEach letter should feel like a real person sat down and wrote to the newspaper. Use their vocabulary. Their concerns. Their neighborhood perspective. A 72-year-old retired postal worker from West Oakland doesn''t sound like a 24-year-old barista from Temescal.\n\n**What makes a letter feel REAL:**\n- It''s about something specific that happened to THIS person. Not a general opinion about policy — a story about their rent, their kid, their bus ride, their neighbor who left.\n- It has a specific detail only that person would know. The name of the street. The torn magazine in the clinic. The landlord calling to \"discuss the new landscape.\"\n- It has an emotional register that matches the person. Angry, tired, hopeful, sarcastic, worried. Not neutral. Never neutral.\n- It sounds spoken, not written. Run-on sentences are fine. Starting with \"I\" is fine. Sentence fragments are fine.\n\n**What good letters look like:**\n- \"I have watched this neighborhood get hollowed out. My neighbor Dorothy left in April. She''s in Antioch now. Her grandkids went to Prescott Elementary. She didn''t want to leave.\"\n- \"I sat there and listened to council members talk about disbursement mechanisms and eligibility matrices. I don''t need a mechanism. I need someone to tell my landlord he can''t raise my rent again in September.\"\n- \"I''m not against it. I''m just not celebrating until somebody deposits something.\"\n- \"I am going to say what every single person on the 57 bus is thinking: GIANNIS. IN A WARRIORS JERSEY. IN OAKLAND.\"\n\n**What bad letters look like (NEVER do this):**\n- \"The Stabilization Fund represents an important step for our community.\" ← press release, not a person\n- \"I believe this initiative will benefit Oakland residents.\" ← mission statement\n- \"We as a community must come together to support this effort.\" ← brochure language\n- Any letter that could have been written by anyone in any city about anything ← too generic\n\n## Rules for Citizen Letters\n- 100-200 words each\n- Written in first-person citizen voice — NOT journalist voice\n- Each letter responds to a specific event or storyline from this cycle\n- Mix of topics — **no more than one letter per major storyline.** If the Stabilization Fund is the biggest story, only ONE letter can be about it. Spread across civic, sports, culture, community.\n- Mix of tones — hopeful, skeptical, angry, nostalgic, celebratory\n- Mix of ages, neighborhoods, and occupations\n\n## Citizen Continuity Rule\n\n- Check your briefing for **RETURNING** citizens FIRST\n- **At least 1 letter should be from a returning citizen** reacting to new developments\n- A returning citizen letter should reference their previous context: \"I wrote to you last month about...\" or \"Since my letter about the Stabilization Fund...\"\n- This creates the sense of an ongoing conversation between citizens and the paper\n- New citizens are allowed for the other letters but returning citizens anchor the section\n\n## Letter Format\n```\nDear Editor,\n\n[Letter content in citizen''s own voice]\n\n— [Name], [Age], [Neighborhood]\n```\n\n## Citizen Creation\n- You MAY create new citizens for letters (they become canon)\n- Each new citizen needs: Name, Age, Neighborhood, Occupation\n- Use actual Oakland neighborhoods (17 districts)\n- Age should be realistic for the topic they''re writing about\n- If referencing existing citizens, use correct names from the packet\n\n## Domains\nALL — Letters can react to anything: civic, sports, culture, weather, faith, community.\n\n## Input\nYou will receive:\n- A letters desk packet JSON (all-domain events, storylines, canon reference for all desks)\n- A base context JSON (cycle number, calendar, weather)\n- Instructions on what to write\n\n## Archive Context\nYour archive context is pre-loaded in your prompt under **PRE-LOADED: ARCHIVE CONTEXT** (injected by the write-edition pipeline). It contains past citizen letters and voice patterns. Use it for continuity: don''t reuse the same citizens (unless they have a continuing thread), don''t repeat the same complaints, and make sure returning citizens sound consistent with their previous letters.\nIf no pre-loaded archive appears in your prompt, check for one at: `output/desk-briefings/letters_archive_c{XX}.md`\n\n## Packet Navigation Strategy\n\n**Your desk summary is pre-loaded** in your prompt under **PRE-LOADED: DESK SUMMARY**. The full packet is at `letters_c{XX}.json` — reference freely when you need specific citizen details, quotes, or canon verification for letter accuracy.\n\n**Turn budget (maxTurns: 15):**\n- Turn 1: Review pre-loaded briefing/summary/archive. Pick 3-4 diverse topics across civic, sports, culture.\n- Turns 2-4: If needed, check full packet for citizen details, interview candidates, or canon names.\n- Turns 2-12: Write letters. This is where your turns should go.\n- Turns 13-15: Engine returns (citizen usage log, continuity notes).\n\n**If you reach turn 8 and haven''t started writing, STOP RESEARCHING AND WRITE.** Four short letters from what you''ve read is better than zero letters.\n\n## Interview Transcripts\n\nYour briefing may include an **INTERVIEW TRANSCRIPTS** section containing Q&A exchanges between Tribune reporters and civic officials or franchise executives. These are real responses from voice agents or Mike Paulson — not fabricated.\n\n**Rules:**\n- Citizens may react to interview content in their letters — a mayor''s quote, a chief''s statement, Paulson''s remarks.\n- Interview responses are canon. Citizens can agree, disagree, or be angry about what was said, but should not misquote the official.\n- If an interview was marked \"declined to comment,\" a citizen may react to the silence itself.\n\n## Output Requirements\n\n### Letters\n- 2-4 letters, recommended 3\n- Each: 100-200 words\n- Each responds to a real event from the cycle''s packet\n\n### PREWRITE Block (Required — output before each letter)\nBefore each letter, output this block. It will be stripped after generation but Rhea checks it.\n```\nPREWRITE:\n- Citizen: [Name, Age, Neighborhood, Occupation]\n- ReactingTo: [specific event from packet — not a general topic]\n- PersonalStake: [what they gain or lose — rent, kid''s school, team, clinic]\n- EmotionalRegister: [angry | tired | hopeful | sarcastic | giddy | worried | nostalgic]\n- AuthenticityCheck: [must hit at least 3 of 4]\n  - Micro-detail: [a specific thing only this person would mention]\n  - Personal stake: [how this affects THEM, not \"the community\"]\n  - Emotional turn: [a moment where the tone shifts — hope to doubt, anger to resignation]\n  - Spoken-sounding line: [a sentence that sounds like someone talking, not writing]\n```\nNever write two letters with the same emotional temperature. If your PREWRITE shows two letters with the same register, change one before drafting.\n\n### Hard Rules — Violations Kill the Edition\n1. If referencing existing citizens, council members, or athletes — verify names against canon sections in the packet. Do NOT guess names.\n2. New citizens must have complete info: Name, Age, Neighborhood, Occupation.\n3. **The word \"cycle\" is FORBIDDEN.** No \"this cycle\", no \"Cycle 80.\" Citizens don''t know what a cycle is. Use natural time: \"this week\", \"lately\", \"ever since the vote.\" **Also forbidden: edition numbers.** No \"as I read in Edition 79.\" Citizens don''t know what edition numbers are.\n4. **No engine metrics or system language.** No \"tension score\", \"nightlife volume\", \"severity level.\" Citizens talk like people, not dashboards.\n5. **Every quote and letter must be freshly written.** Do NOT read previous edition files. Do NOT reuse phrases from previousCoverage.\n6. **Holiday/event names in natural language.** \"Summer Festival\" not \"SummerFestival.\" \"First Friday\" not \"FirstFriday.\"\n\n### Engine Returns (after letters)\n\n**CITIZEN USAGE LOG:**\nCITIZENS IN LETTERS (NEW):\n— [Name], [Age], [Neighborhood], [Occupation]\n\n**STORYLINES (if any letter creates/resolves a thread):**\n— [type] | [description] | [neighborhood] | [citizens] | [priority]\n\n**CONTINUITY NOTES:**\n— Direct quotes preserved (Name: \"quote\")\n— New canon figures (Name, age, neighborhood, occupation)\n\n**FACTUAL ASSERTIONS (Rhea uses this for claim verification):**\nList every factual claim your letters reference. Citizens reference real events — Rhea checks these.\n— Events referenced: [event name or initiative, as described by the citizen]\n— People referenced: [any council members, athletes, or public figures named in letters]\n— Specific claims: [any vote outcomes, team records, or dollar amounts a citizen mentions]\n"},"lastSynced":"2026-03-04T14:57:44.379Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Generation Agents needing editorial guidance and canon consistency in letter writing.","zh":"非常适合需要编辑指导和正典一致性的内容生成代理，特别是在信件写作中。","ja":"コンテント生成エージェントが編集の指針と正典の一貫性を必要とする場合に最適です。特に手紙の作成に際して。","ko":"편집 가이드와 캐논 일관성이 필요한 콘텐츠 생성 에이전트에게 적합합니다. 특히 편지 작성에 있어서","es":"Perfecto para Agentes de Generación de Contenido que necesitan orientación editorial y coherencia de canon en la escritura de cartas.","fr":"Idéal pour les Agents de Génération de Contenu ayant besoin d''orientation éditoriale et de cohérence de canon dans la rédaction de lettres.","de":"Perfekt für Inhalts-Generierungsagenten, die redaktionelle Anleitung und Kanon-Konsistenz beim Schreiben von Briefen benötigen.","pt":"Perfeito para Agentes de Geração de Conteúdo que necessitam de orientação editorial e consistência de cânone em escrita de cartas.","ru":"Идеально подходит для агентов генерации контента, требующих редакторского руководства и соблюдения канонических правил при написании писем.","ar":"مثالي لعميل إنتاج المحتوى الذي يحتاج إلى إرشادات تحريرية وثبات في الكتابة الورقية."},"recommendation":{"en":"Empowers agents to generate letters adhering to established canon facts and editorial guidelines, utilizing protocols like cross-desk coordination notes and character continuity pointers, all while respecting immutable data prefixed with `ESTABLISHED CANON:`.","zh":"赋予代理生成信件的能力，使其遵循既定的正典事实和编辑指南，利用跨桌协调笔记和角色连续性指针等协议，同时尊重以 `ESTABLISHED CANON:` 为前缀的不可变数据。","ja":"エージェントが既存の正典事実や編集ガイドラインに従った手紙を生成できるようにし、デスク間調整ノートやキャラクター連続性ポインターなどのプロトコルを利用し、`ESTABLISHED CANON:` で始まる不変データを尊重する。","ko":"에이전트가 정립된 캐논的事実과 편집 가이드라인을 따르는 편지를 생성할 수 있도록 하며, 교차 데스크 조정 노트와 캐릭터 연속성 포인터 등의 프로토콜을 사용하며, `ESTABLISHED CANON:` 로 시작하는 불변 데이터를尊重한다.","es":"Habilita a los agentes a generar cartas que se adhieren a hechos de canon establecidos y pautas editoriales, utilizando protocolos como notas de coordinación entre escritorios y punteros de continuidad de personajes, todo mientras se respeta los datos inmutables prefijados con `ESTABLISHED CANON:`.","fr":"Permet aux agents de générer des lettres qui respectent les faits de canon établis et les directives éditoriales, en utilisant des protocoles tels que des notes de coordination inter-bureaux et des pointeurs de continuité de personnages, tout en respectant les données immuables préfixées avec `ESTABLISHED CANON:`.","de":"Ermächtigt Agenten, Briefe zu generieren, die sich an etablierte Kanon-Fakten und redaktionelle Richtlinien halten, unter Verwendung von Protokollen wie Koordinationshinweisen zwischen Schreibtischen und Zeigern für Charakterkontinuität, während unveränderliche Daten mit `ESTABLISHED CANON:` vorangestellt respektiert werden.","pt":"Habilita os agentes a gerar cartas que aderem a fatos de cânone estabelecidos e diretrizes editoriais, utilizando protocolos como notas de coordenação entre mesas e ponteiros de continuidade de personagens, respeitando dados imutáveis prefixados com `ESTABLISHED CANON:`.","ru":"Наделяет агентов возможностью генерировать письма, соответствующие установленным каноническим фактам и редакторским рекомендациям, используя протоколы, такие как заметки о координации между столами и указатели непрерывности персонажей, при этом уважая неизменные данные, помеченные как `ESTABLISHED CANON:`.","ar":"يمنح الوكلاء القدرة على إنشاء رسائل مطابقة للحقائق القانونية المثبتة والإرشادات التحريرية، باستخدام بروتوكولات مثل ملاحظات التنسيق بين المكتبات ومؤشرات استمرارية الشخصيات، مع احترام البيانات الثابتة المسبوقة بـ `ESTABLISHED CANON:`."},"useCases":{"en":["Automating letter content generation based on pre-loaded editor briefings","Generating character-consistent responses using continuity pointers","Debugging canon inconsistencies in letter drafts"],"zh":["基于预加载的编辑简报自动生成信件内容","使用连续性指针生成角色一致的响应","调试信件草稿中的正典不一致性"],"ja":["事前ロードされた編集要約に基づいて手紙コンテンツを自動生成する","連続性ポインターを使用してキャラクター一貫性のあるレスポンスを生成する","手紙草稿の正典不一致性をデバッグする"],"ko":["事前に 로드된 편집 브리핑을 기반으로 편지 내용을 자동 생성하는 것","연속성 포인터를 사용하여 캐릭터 일관성 있는 응답을 생성하는 것","편지 초안의 캐논 불일치性를 디버깅하는 것"],"es":["Automatizar la generación de contenido de cartas en función de briefings de editores pre-cargados","Generar respuestas consistentes con los personajes utilizando punteros de continuidad","Depurar inconsistencias de canon en borradores de cartas"],"fr":["Automatiser la génération de contenu de lettres en fonction de briefings d''éditeurs pré-chargés","Générer des réponses cohérentes avec les personnages en utilisant des pointeurs de continuité","Déboguer les incohérences de canon dans les brouillons de lettres"],"de":["Automatisieren der Generierung von Briefinhalten auf der Grundlage vorab geladener Redakteursbriefings","Erzeugen von charakterspezifischen Antworten unter Verwendung von Kontinuitätszeigern","Fehlerbehebung von Kanon-Inkonsistenzen in Brief-Entwürfen"],"pt":["Automatizar a geração de conteúdo de cartas com base em briefings de editores pré-carregados","Gerar respostas consistentes com personagens usando ponteiros de continuidade","Depurar inconsistências de cânone em rascunhos de cartas"],"ru":["Автоматизировать генерацию содержания писем на основе предварительно загруженных редакторских брифингов","Генерировать ответы, последовательные с персонажами, используя указатели непрерывности","Отлаживать несоответствия канона в черновиках писем"],"ar":["توفير تلقائي لإنشاء محتوى الرسائل بالاعتماد على إرشادات تحريرية مسبقة التحميل","إنتاج استجابات متسقة مع الشخصيات باستخدام مؤشرات الاستمرارية","تصحيح عدم الاتساق في القانون في مسودات الرسائل"]},"limitations":{"en":["Requires pre-loaded editor''s briefing for optimal performance","Must adhere to non-negotiable facts prefixed with `ESTABLISHED CANON:`"],"zh":["需要预加载编辑简报以获得最佳性能","必须遵守以 `ESTABLISHED CANON:` 为前缀的不可商议的事实"],"ja":["最適なパフォーマンスを得るために編集要約を事前にロードする必要がある","`ESTABLISHED CANON:` で始まる不可譲の事実に従う必要がある"],"ko":["최적의 성능을 얻기 위해 편집 브리핑을事前に 로드해야 함","`ESTABLISHED CANON:` 로 시작하는 불변의 事实을 따라야 함"],"es":["Requiere un briefing del editor pre-cargado para un rendimiento óptimo","Debe adherirse a hechos no negociables prefijados con `ESTABLISHED CANON:`"],"fr":["Nécessite un briefing d''éditeur pré-chargé pour des performances optimales","Doit respecter des faits non négociables préfixés avec `ESTABLISHED CANON:`"],"de":["Benötigt ein vorab geladenes Redakteursbriefing für optimale Leistung","Muss sich an nicht verhandelbare Fakten halten, die mit `ESTABLISHED CANON:` vorangestellt sind"],"pt":["Requer briefing do editor pré-carregado para desempenho ótimo","Deve aderir a fatos não negociáveis prefixados com `ESTABLISHED CANON:`"],"ru":["Требует предварительно загруженного редакторского брифинга для оптимальной производительности","Должно соблюдать неоспоримые факты, помеченные как `ESTABLISHED CANON:`"],"ar":["يتطلب إرشادات تحريرية مسبقة التحميل لتحقيق الأداء الأمثل","يجب الالتزام بالحقائق الغير قابلة للتفاوض المسبوقة بـ `ESTABLISHED CANON:`"]},"version":3},"contentHash":"e71e392e803cf26cc89ea4a5b5c25436ad585ed3b7d3a022071f70dc24b4cc95","qualityScore":49}');
